/** The normalized form of text that every match and key compares. */

export function normalize(text: string): string {
  return text.toLowerCase().replace(/[*_`[\]()]/g, '').replace(/\s+/g, ' ').trim()
}

files.hooks/id-blocks.ts:
/**
 * The ID blocks a session claims (UCR-030, UCR-041): the block of an ID value, the claim name to make
 * for a block, and the free IDs a claimed block gives.
 *
 * Why blocks: the engine store has only get and set, so two sessions that read the reservations before
 * either writes can both take one ID. A session instead claims a block of BLOCK_SIZE ID values by
 * making an entry named for the block in the repo's claim folder, with a create that fails when the
 * name is taken (`mkdir` without `-p`; on Windows a file opened CreateNew). The OS makes that atomic,
 * so one block has one holder, and its IDs are given out with no store round trip.
 *
 * A claim goes stale CLAIM_MS after it was made: a later session may then take the block over by
 * making the next generation's name (`<block>.<gen + 1>`), which is just as atomic. The holder gives
 * out new IDs from its block only for CLAIM_USE_MS, so every ID it named (reserved for RESERVE_MS)
 * stays covered by a live claim.
 */

import { nextTicketIds, RESERVE_MS, ticketValue, VALUE_END } from './ticket-ids'

/** ID values per block: small, since a block a session leaves half used is a gap in the numbers. */
export const BLOCK_SIZE = 8
/** How long a session gives out new IDs from a block after it claimed it. */
export const CLAIM_USE_MS = RESERVE_MS
/** How old a claim is when another session may take its block over: past every reservation its holder made. */
export const CLAIM_MS = CLAIM_USE_MS + RESERVE_MS
/** Blocks tried per claim, upward from the first free one, before the claim gives up. */
export const CLAIM_SCAN = 64

/** The block an ID value falls in. */
export const blockOf = (value: number): number => Math.floor(value / BLOCK_SIZE)

/** A claim entry's name: the block, and from the first takeover on, the generation. */
export const claimName = (block: number, gen: number): string => (gen === 0 ? `${block}` : `${block}.${gen}`)

/** The block and generation a claim entry's name gives; undefined for any other name. */
export function parseClaim(name: string): { block: number; gen: number } | undefined {
  const m = /^(\d+)(?:\.(\d+))?$/.exec(name)

  return m === null ? undefined : { block: Number(m[1]), gen: m[2] === undefined ? 0 : Number(m[2]) }
}

/**
 * The name to make to claim `block`, given the claim folder's entries: the first generation when the
 * block has none, the next one when its newest claim is stale (older than CLAIM_MS at `now`), and
 * undefined while another claim on it is live.
 */
export function nextClaim(entries: readonly { name: string; mtimeMs: number }[], block: number, now: number): string | undefined {
  let newest: { gen: number; mtimeMs: number } | undefined
  for (const entry of entries) {
    const claim = parseClaim(entry.name)
    if (claim !== undefined && claim.block === block && (newest === undefined || claim.gen > newest.gen)) {
      newest = { gen: claim.gen, mtimeMs: entry.mtimeMs }
    }
  }
  if (newest === undefined) {
    return claimName(block, 0)
  }

  return now - newest.mtimeMs >= CLAIM_MS ? claimName(block, newest.gen + 1) : undefined
}

/** The block the next free ID above every one of `taken` falls in: where a new claim starts. */
export function firstBlock(taken: Iterable<string>): number {
  const next = nextTicketIds(taken, 1)[0]

  // Past the end of the number line (UCR-142): the block just past it, which gives no ID.
  return next === undefined ? blockOf(VALUE_END) : blockOf(ticketValue(next)!)
}

/**
 * Up to `count` free IDs of `block`, above every ID of `taken` that falls in the block or below it.
 * An ID of `taken` above the block (one another session gave from a later block) does not end it
 * (UCR-119): while the claim holds, the block is this session's alone, so its free values stay free.
 * So the rule "a new ID comes after the highest one in use" holds per new block: a block is claimed
 * at the first free value, and IDs go up inside it from the highest one in use in it. Fewer, or none,
 * when the block runs out.
 */
export function blockIds(taken: Iterable<string>, block: number, count: number): string[] {
  const start = block * BLOCK_SIZE
  const end = start + BLOCK_SIZE
  const inBlock = [...taken].filter(id => {
    const value = ticketValue(id)

    return value !== undefined && value < end
  })

  // The floor is the value just below the block, as a number (UCR-142): an ID form of it may not exist (one past
  // VALUE_END), and a floor that was dropped gave IDs from below the block.
  return nextTicketIds(inBlock, count, start - 1).filter(id => blockOf(ticketValue(id)!) === block)
}

/** The block a session gives IDs from, and when it claimed it (clock ms). */
export type HeldBlock = { block: number; claimedAt: number }

/**
 * True when the session must claim a new block before it gives an ID: it has none, its block ran out
 * (`isSpent`), or CLAIM_USE_MS passed since its claim. Never because another session's IDs passed
 * the block (UCR-119): that made every pick of two sessions taking turns claim a new block.
 */
export const needsBlock = (held: HeldBlock | undefined, isSpent: boolean, time: number): boolean => held === undefined || isSpent || time - held.claimedAt >= CLAIM_USE_MS

/** The block a new claim starts at: the first free one, and past the session's last block. */
export const claimFrom = (held: HeldBlock | undefined, first: number): number => (held === undefined ? first : Math.max(first, held.block + 1))

/** How often a session deletes the claims no one needs any more (UCR-120). */
export const CLAIM_PRUNE_MS = 60 * 60 * 1000

/**
 * The claim entries that can go (UCR-120): the older generations of a block below `first` (the block
 * of the next free ID: no new claim starts there, and every ID of it is used or passed) whose newest
 * claim is stale at `now` (its holder gives no new ID from it, and every reservation it made has
 * ended). A live claim, a block at or above `first`, and a name that is no claim are kept.
 *
 * The newest generation of a block is never deleted (UCR-147). The delete goes by name, from a list
 * made before it: had the newest name gone, another session could make that name again as a live
 * claim (the first generation of a block with no entries) between the list and the delete, and the
 * delete would end the live claim. While the newest name stays, every new claim of the block takes a
 * higher generation, so a deleted name is never made again. The cost: one empty entry stays per
 * block ever claimed (8 IDs each).
 */
export function prunableClaims(entries: readonly { name: string; mtimeMs: number }[], first: number, now: number): string[] {
  const newest = new Map<number, { gen: number; mtimeMs: number }>()
  for (const entry of entries) {
    const claim = parseClaim(entry.name)
    const was = claim === undefined ? undefined : newest.get(claim.block)
    if (claim !== undefined && (was === undefined || claim.gen > was.gen)) {
      newest.set(claim.block, { gen: claim.gen, mtimeMs: entry.mtimeMs })
    }
  }

  return entries
    .filter(entry => {
      const claim = parseClaim(entry.name)
      const top = claim === undefined ? undefined : newest.get(claim.block)

      return claim !== undefined && top !== undefined && claim.gen < top.gen && claim.block < first && now - top.mtimeMs >= CLAIM_MS
    })
    .map(entry => entry.name)
}

/** The claim folder inside a git common dir: per repo, shared by every worktree, never committed. */
export const gitClaimDir = (common: string): string => `${common}/claudeopticon/id-claims`

/** The claim folder in a folder's `.claude_work/`, which the export leaves out. */
export const workClaimDir = (base: string): string => `${base}/.claude_work/claudeopticon-id-claims`

/**
 * Where a session claims ID blocks (UCR-030, UCR-118). `main`: in the git common dir (absolute, from
 * `git rev-parse --git-common-dir`, or read from the `.git` entry when git fails), in every git layout
 * (a `.git` folder, a `.git` file of a separate git dir or a submodule, a linked worktree, a bare repo's
 * worktree), so every session of the repo claims in one folder.
 *
 * `fallback`: claimed in only when the main folder cannot be made (a read-only `.git`), and listed by
 * every claim either way (UCR-136, `claimAcross`). That check is sound only when every session of the
 * repo names the same fallback, so it comes from the common dir alone, never from the session's own
 * checkout: only a common dir `<root>/.git` gives one, `<root>/.claude_work/`. A bare repo, a separate
 * git dir or a submodule has no folder every worktree shares but the common dir, so it gets no fallback:
 * a session that cannot write its common dir names no IDs there (UCR-136). The per-worktree fallback
 * this replaces gave each worktree its own folder, and two sessions held one block.
 *
 * With no git at all, the primary todo folder's parent (`looseBase`) keys the one folder, never the
 * nearest todo folder of a session in a subfolder.
 */
export function claimDirs(where: { common?: string; looseBase?: string }): { main?: string; fallback?: string } {
  if (where.common !== undefined) {
    const common = where.common.replace(/\/+$/, '')
    const root = common.endsWith('/.git') ? common.slice(0, -'/.git'.length) : undefined

    return { main: gitClaimDir(common), ...(root === undefined || root === '' ? {} : { fallback: workClaimDir(root) }) }
  }

  return where.looseBase === undefined ? {} : { main: workClaimDir(where.looseBase) }
}

files.hooks/block-claim.ts:
/**
 * The claim of one ID block across the repo's two claim folders (UCR-136), over a small file port, so
 * the engine and a race script of real processes run the same steps.
 *
 * Why two folders: a session claims in the git common dir, and in the repo's `.claude_work/` folder
 * only when the git folder cannot be made (UCR-118). Sessions of one repo can so claim in different
 * folders (one `mkdir -p` that failed once, a read-only `.git`, a session whose git call fails). A
 * claim is atomic inside one folder only, so a session lists both folders before it claims, and after
 * its own claim is made it lists the other folder again: when that folder now holds a claim on the
 * same block (a new name, or a live one), the session gives the block up (deletes its own claim) and
 * tries the next. Of two sessions that claim one block in two folders, each makes its claim before it
 * looks at the other folder, so at least one of them sees the other's claim: never both keep it. Both
 * may give it up; the block is then a gap in the numbers, never a duplicate.
 */

import { BLOCK_SIZE, blockOf, CLAIM_MS, CLAIM_SCAN, nextClaim, parseClaim } from './id-blocks'
import { VALUE_END } from './ticket-ids'

/** The first block past the end of the number line (UCR-197): it holds no ID value, so it is never claimed. */
export const END_BLOCK = blockOf(VALUE_END - 1) + 1

/** One entry of a claim folder: its name and when it was made (ms). */
export type ClaimEntry = { name: string; mtimeMs: number }

/** The file calls a claim makes. */
export type ClaimPort = {
  /** The folder's entries; undefined when it will not list. */
  list: (dir: string) => Promise<ClaimEntry[] | undefined>
  /** True when something stands at the path; a check that fails must say true. */
  exists: (path: string) => Promise<boolean>
  /** Makes the entry only if nothing stands at its name, atomically. */
  make: (path: string) => Promise<'made' | 'taken' | 'failed'>
  /** Deletes an entry this session made; true when it is gone. */
  remove: (path: string) => Promise<boolean>
}

/** A claim made: the block, and the path of its entry (to delete it when its IDs go unused). */
export type MadeClaim = { block: number; path: string }

/**
 * The entries of the other claim folder: none when there is no other folder or nothing stands at it
 * (no session made a claim there: its `mkdir -p` comes before its claim), undefined when it is there
 * and will not list (then no claim can be told safe).
 */
export async function otherEntries(port: ClaimPort, other: string | undefined): Promise<ClaimEntry[] | undefined> {
  if (other === undefined) {
    return []
  }
  const listed = await port.list(other)
  if (listed !== undefined) {
    return listed
  }

  return (await port.exists(other)) ? undefined : []
}

/**
 * True when the other folder (`now`) holds a claim on `block` this session must give way to: one whose
 * name the list before the claim (`before`) did not have, or one that is live at `time`.
 */
export function mustYield(now: readonly ClaimEntry[], before: readonly ClaimEntry[], block: number, time: number): boolean {
  const was = new Set(before.map(entry => entry.name))

  return now.some(entry => {
    const claim = parseClaim(entry.name)

    return claim !== undefined && claim.block === block && (!was.has(entry.name) || time - entry.mtimeMs < CLAIM_MS)
  })
}

/**
 * Claims the first block from `from` up that no live claim holds in either folder (`nextClaim` over
 * both lists): in `dir`, with `own` its entries (listed, pruned), and `other` the repo's other claim
 * folder. A block another session claimed first in `dir` is passed over; one the other folder shows
 * after the claim is given up (the claim deleted) and passed over. The scan stops at the end of the
 * number line (END_BLOCK, UCR-197): a block past it gives no ID, and claiming it made 64 entries per
 * pick for nothing. The claim made, or the reason as text when the other folder will not list, a claim
 * fails, every block scanned is held, or no block is left on the number line.
 */
export async function claimAcross(port: ClaimPort, dir: string, other: string | undefined, own: readonly ClaimEntry[], from: number, time: number): Promise<MadeClaim | string> {
  if (from >= END_BLOCK) {
    return 'the number line of ticket IDs is used up'
  }
  const before = await otherEntries(port, other)
  if (before === undefined) {
    return `could not list ${other!}`
  }
  const entries = [...own, ...before]
  for (let block = from; block < Math.min(from + CLAIM_SCAN, END_BLOCK); block += 1) {
    const name = nextClaim(entries, block, time)
    if (name === undefined) {
      continue
    }
    const path = `${dir}/${name}`
    const got = await port.make(path)
    if (got === 'taken') {
      continue
    }
    if (got === 'failed') {
      return `could not make ${path}`
    }
    const after = await otherEntries(port, other)
    if (after !== undefined && !mustYield(after, before, block, time)) {
      return { block, path }
    }
    // Given up: the other folder holds the block too, or cannot be told. A delete that fails leaves an unused block.
    await port.remove(path)
    if (after === undefined) {
      return `could not list ${other!}`
    }
    entries.push(...after)
  }

  return `every block from ${from * BLOCK_SIZE} on is claimed`
}

files.hooks/git-file.ts:
/**
 * The git common dir read from a `.git` entry, with no git (UCR-136): for a session whose `git rev-parse`
 * fails (dubious ownership, another HOME, no git on PATH, a timeout), so it still finds the claim folders
 * every git session of the repo uses. The claim folders come from the common dir alone (`claimDirs`), so
 * the common dir is all this reads.
 */

import { isAbsPath, resolveAgainst } from './path-forms'

/** Where a `.git` entry puts the repo: the common dir, absolute. */
export type GitWhere = { common: string }

/** A `.git` folder at `folder`: the common dir is that folder. */
export const gitDirWhere = (folder: string): GitWhere => ({ common: `${folder}/.git` })

/**
 * The git dir a `.git` file at `folder` names (its text `gitdir: <dir>`), absolute. Undefined for a text with
 * no `gitdir:` line, or one that gives no absolute path.
 */
export function gitFileDir(folder: string, text: string): string | undefined {
  const named = /^gitdir:\s*(.+)$/m.exec(text)?.[1]?.replace(/\r$/, '').trim()
  if (named === undefined || named === '') {
    return undefined
  }
  const gitdir = resolveAgainst(folder, named).replace(/\/+$/, '')

  return isAbsPath(gitdir) ? gitdir : undefined
}

/**
 * The common dir of a git dir, by git's own rule (UCR-202, `get_common_dir_noenv` in git's setup.c): when
 * `<gitdir>/commondir` exists (a linked worktree's git dir holds one, `../..`), the common dir is its text,
 * line ends cut, resolved against the git dir; when it does not (`commondir` undefined), the git dir is the
 * common dir. A path segment named `worktrees` says nothing: the old cut at the last `/worktrees/` put a
 * separate git dir under `.../worktrees/proj.git`, and a submodule named `worktrees`, in a folder no git
 * session names.
 */
export function commonDirOf(gitdir: string, commondir: string | undefined): GitWhere {
  if (commondir === undefined) {
    return { common: gitdir }
  }

  return { common: resolveAgainst(gitdir, commondir.replace(/[\r\n]+$/, '')).replace(/\/+$/, '') }
}

/** The folders from `start` up to the file system root, nearest first, at most `max`. */
export function foldersUp(start: string, max: number): string[] {
  const out: string[] = []
  let at = start.replace(/\/+$/, '')
  while (at !== '' && out.length < max) {
    out.push(at)
    const cut = at.lastIndexOf('/')
    at = cut <= 0 ? '' : at.slice(0, cut)
  }

  return out
}

/** The file calls of the `.git` walk, apart from the engine so a probe or a test can run it on a real or a fake disk. A call that fails gives undefined. */
export type GitFs = {
  exists: (path: string) => Promise<boolean | undefined>
  kind: (path: string) => Promise<string | undefined>
  read: (path: string) => Promise<string | undefined>
}

/**
 * The repo's git common dir from the `.git` entry nearest `base` and above it, up to the file system
 * root, as git walks (UCR-136: a limit of 9 folders left a deep todo folder claiming where no git
 * session lists). Undefined when no `.git` shows; `unknown` when a check fails, or a `.git` shows that
 * does not read or name a git dir: then no folder is safe (its git sessions may claim in a folder this
 * session cannot name), and no ID is given.
 */
export async function gitWhereUp(fs: GitFs, base: string): Promise<GitWhere | 'unknown' | undefined> {
  for (const folder of foldersUp(base, Number.POSITIVE_INFINITY)) {
    const path = `${folder}/.git`
    const isThere = await fs.exists(path)
    if (isThere === undefined) {
      return 'unknown'
    }
    if (!isThere) {
      continue
    }
    const kind = await fs.kind(path)
    if (kind === 'dir') {
      return gitDirWhere(folder)
    }
    const text = kind === 'file' ? await fs.read(path) : undefined
    const gitdir = text === undefined ? undefined : gitFileDir(folder, text)
    if (gitdir === undefined) {
      return 'unknown'
    }
    // The `commondir` file decides (UCR-202); a check or a read of it that fails names no folder.
    const commondir = `${gitdir}/commondir`
    const hasCommondir = await fs.exists(commondir)
    if (hasCommondir === undefined) {
      return 'unknown'
    }
    const linked = hasCommondir ? await fs.read(commondir) : undefined
    if (hasCommondir && linked === undefined) {
      return 'unknown'
    }

    return commonDirOf(gitdir, linked)
  }

  return undefined
}

