/** The text work of numbering: the ID a line has, and IDs written into lines that have none. */

import { bare, CHECKBOX, ID_SRC, parseTodo, plainText } from './todo-markdown'

export const NUMBER_AFTER_MS = 5000

/**
 * The most lines of one file numbered in one pass (UCR-137); the rest wait for the next pass. One
 * pick claims at most CLAIM_SCAN blocks of BLOCK_SIZE IDs (512), and fewer when other sessions hold
 * some: 128 leaves room for that, so a file of many new lines never asks for more than a pick gives.
 */
export const NUMBER_MAX = 128

/** Every ID word of the line (`#` dropped). */
const ID_WORDS = new RegExp(`#(${ID_SRC})\\b`, 'g')

/**
 * Every ID word a checkbox line carries (no `#`), in order (UCR-145): an example line `- [ ] see #h264
 * and #T0099` holds `T0099` as well, so its value counts as taken. Empty for a line with none.
 */
export function lineIds(line: string): string[] {
  const m = CHECKBOX.exec(line)

  return m === null ? [] : [...plainText(m[2] ?? '').matchAll(ID_WORDS)].map(word => word[1]!)
}

/**
 * The first checkbox line of `text` that holds the ID word `#<id>` (any case), trimmed; undefined when none
 * does. For a toast that names where an ID is (UCR-197). Only checkbox lines count (`lineIds`, UCR-208), as
 * only their IDs move the next IDs: a prose line that names the ID is never the line to edit.
 */
export function lineHolding(text: string, id: string): string | undefined {
  const want = id.toLowerCase()

  return text
    .split('\n')
    .map(bare)
    .find(line => lineIds(line).some(word => word.toLowerCase() === want))
    ?.trim()
}

/** Every item ID a todo file's text holds, lowercase: the parser's, and every ID word of each checkbox line, examples included. */
export function textIds(text: string): string[] {
  const ids = parseTodo(text).flatMap(item => (item.id === undefined ? [] : [item.id.toLowerCase()]))
  for (const line of text.split('\n').map(bare)) {
    ids.push(...lineIds(line).map(id => id.toLowerCase()))
  }

  return ids
}

/**
 * The text with `ids` inserted, in order, right after the box of each line in `at` (line indexes):
 * `- [ ] Fix x` becomes `- [ ] #T002B Fix x`.
 */
export function insertIds(text: string, at: readonly number[], ids: readonly string[]): string {
  const lines = text.split('\n')
  at.forEach((index, i) => {
    lines[index] = lines[index]!.replace(/^(\s*[-*+] \[[ xX~>]\]\s+)/, `$1#${ids[i]!} `)
  })

  return lines.join('\n')
}

files.hooks/orchestrator-history.ts:
/** The Orchestrator history: its entries and its pages. */

/**
 * What the main conversation (the orchestrator) did itself this session: the one-line summary of
 * each of its tool calls (the call's own `description`, as the transcript shows it), with its start
 * time, newest last, the last 1000 kept. Agent calls stay out: they are the agents' work.
 */
export type OrchestratorEntry = { id: number; line: string; at: number; isRunning: boolean; detail?: string }

export const ORCHESTRATOR_KEPT = 1000
export const ORCHESTRATOR_PAGE = 5

/** "Newest 5 of 57" on the first page, then "11 to 15 of 57". */
export function pageLabel(view: { entries: readonly unknown[]; page: number }, total: number): string {
  const from = view.page * ORCHESTRATOR_PAGE + 1

  return view.page === 0 ? `Newest ${view.entries.length} of ${total}` : `${from} to ${from + view.entries.length - 1} of ${total}`
}

/** One page of the history, newest first, and how many pages there are; a page past the end shows the last. */
export function orchestratorView(history: readonly OrchestratorEntry[], page: number): { entries: OrchestratorEntry[]; page: number; pages: number } {
  const pages = Math.max(1, Math.ceil(history.length / ORCHESTRATOR_PAGE))
  const at = Math.min(Math.max(0, page), pages - 1)
  const newest = [...history].reverse()

  return { entries: newest.slice(at * ORCHESTRATOR_PAGE, (at + 1) * ORCHESTRATOR_PAGE), page: at, pages }
}

files.hooks/path-forms.ts:
/** Path forms: Windows paths, PowerShell quoting, normalized comparison, relative paths and folders named by the environment. */

/**
 * A PowerShell expression for a path, built from its UTF-16 character codes: digits and commas only, so no
 * character in a file name (straight or curly quote, `$`, backtick) can end the string or run code.
 */
export function psPath(path: string): string {
  // UTF-16 code units, as `[char]` takes them: a name outside the BMP is two units (a surrogate pair), not one code point.
  const flat = path.replace(/\//g, '\\')

  return `[string]::new([char[]](${Array.from({ length: flat.length }, (_, i) => flat.charCodeAt(i)).join(',')}))`
}

/** True for a Windows absolute path, `C:/x` or `C:\x`. */
export const isWinPath = (path: string): boolean => /^[A-Za-z]:[\\/]/.test(path)

/** A Windows path with forward slashes and an upper-case drive letter, so two spellings compare equal. Any other path is returned as it is (a backslash is a legal POSIX name character). */
export function normPath(path: string): string {
  return isWinPath(path) ? path.replace(/\\/g, '/').replace(/^[a-z]:/, drive => drive.toUpperCase()) : path
}

/** A path made absolute against `base` with `.` and `..` segments folded; an absolute path is only folded. */
export function resolveAgainst(base: string, path: string): string {
  const isAbs = path.startsWith('/') || /^[A-Za-z]:\//.test(path)
  const parts = (isAbs ? path : `${base}/${path}`).split('/')
  const out: string[] = []
  for (const part of parts.slice(1)) {
    if (part === '..') {
      out.pop()
    } else if (part !== '' && part !== '.') {
      out.push(part)
    }
  }

  return `${parts[0]}/${out.join('/')}`
}

/**
 * A path with `.` and `..` segments folded and no trailing slash, absolute or relative (UCR-202): a
 * relative path keeps the `..` segments that lead out of its start (`../../x`), which
 * `resolveAgainst` cannot, as it needs an absolute base. A Windows path gets forward slashes first.
 * An empty relative result is `.`.
 */
export function foldPath(path: string): string {
  const flat = normPath(path)
  const lead = flat.startsWith('/') ? '/' : (/^[A-Z]:\//.exec(flat)?.[0] ?? '')
  const out: string[] = []
  for (const part of flat.slice(lead.length).split('/')) {
    if (part === '..' && out.length > 0 && out[out.length - 1] !== '..') {
      out.pop()
    } else if (part === '..' && lead === '') {
      out.push(part)
    } else if (part !== '' && part !== '.' && part !== '..') {
      out.push(part)
    }
  }
  const body = out.join('/')

  return lead === '' ? body || '.' : `${lead}${body}`
}

/** A real path from the repo root, or undefined when it lies outside the root. */
export function relIn(real: string | undefined, root: string | undefined): string | undefined {
  return real !== undefined && root !== undefined && real.startsWith(`${root}/`) ? real.slice(root.length + 1) : undefined
}

/** Two spellings of one path: Windows drive and slashes folded, and Unicode in NFC (macOS gives file names in NFD, git in NFC). */
export function samePath(a: string, b: string): boolean {
  return normPath(a).normalize('NFC') === normPath(b).normalize('NFC')
}

/**
 * True when git's session folder (`sessionFolder` of the REV_PARSE output) is the session's own folder,
 * the real path of `.` (UCR-150). Both must be known. A Windows path may differ in letter case too, as
 * that disk ignores it; a POSIX path must match exactly (NFC aside), since a case-sensitive disk can
 * hold both spellings as two folders.
 */
export function isSameFolder(gitSays: string | undefined, real: string | undefined): boolean {
  if (gitSays === undefined || real === undefined) {
    return false
  }
  const [a, b] = [gitSays, real].map(path => normPath(path).replace(/(.)\/+$/, '$1'))

  return samePath(a!, b!) || (isWinPath(a!) && caseKey(a!) === caseKey(b!))
}

/** One spelling of a path with letter case folded too, for disks that ignore case (macOS and Windows by default). */
const caseKey = (path: string): string => normPath(path).normalize('NFC').toLowerCase()

/**
 * True when two paths differ only by letter case (UCR-151): after a case-only rename on a disk that
 * ignores case, git lists the old case (`Docs/`) while the real path has the new one (`docs/`).
 */
export function isCaseOnly(listed: string, real: string): boolean {
  return !samePath(listed, real) && caseKey(listed) === caseKey(real)
}

/**
 * The name a folder's own listing gives to `name` (UCR-152): `name` itself when it is listed; else the
 * one entry that matches it without case (`todo.md` for `TODO.md`); else `name`. Two entries that match
 * without case (a disk that keeps case apart) give `name`, so no other file is taken for it.
 */
export function listedName(names: readonly string[], name: string): string {
  if (names.includes(name)) {
    return name
  }
  const near = names.filter(one => caseKey(one) === caseKey(name))

  return near.length === 1 ? near[0]! : name
}

/** True for an absolute path, POSIX (`/x`) or Windows (`C:/x`, `C:\x`). */
export const isAbsPath = (path: string): boolean => path.startsWith('/') || isWinPath(path)

/**
 * The forms of a folder named by an environment variable (HOME, USERPROFILE, CLAUDE_CONFIG_DIR), with
 * no trailing slash: a POSIX path as it is; a Windows path with forward slashes and an upper-case drive
 * (`d:\cfg\` gives `D:/cfg`); an MSYS path (`/d/cfg`, as Git for Windows tools print it) also as the
 * Windows path it stands for. Empty for a value that is not an absolute path (UCR-023).
 */
export function envDirs(value: string | undefined): string[] {
  const text = value?.trim() ?? ''
  if (!isAbsPath(text)) {
    return []
  }
  const bare = normPath(text).replace(/\/+$/, '')
  const one = bare === '' ? '/' : /^[A-Z]:$/.test(bare) ? `${bare}/` : bare
  const msys = /^\/([A-Za-z])(\/.*)?$/.exec(one)

  return msys === null ? [one] : [one, `${msys[1]!.toUpperCase()}:${msys[2] ?? '/'}`]
}

files.hooks/platform-commands.ts:
/** The system commands per platform: which platform it is, the opener, and why a trash command failed. */

import { isWinPath } from './path-forms'

/**
 * Files only macOS has, read when `uname -s` gives nothing (UCR-022). `sw_vers` and `osascript` ship
 * with every macOS. `/usr/bin/trash` is no sign: trash-cli installs it on Linux (UCR-022).
 */
export const MAC_SIGNS = ['/usr/bin/sw_vers', '/usr/bin/osascript']

/** The platform name: the `uname -s` answer, else `Darwin` when a macOS file is there, else empty (unknown). */
export function platformFrom(uname: string, hasMacSign: boolean): string {
  return uname !== '' ? uname : hasMacSign ? 'Darwin' : ''
}

/**
 * The command line that opens an absolute file path in the OS default app. No shell, and the path
 * is absolute, so it cannot look like a flag.
 */
export function openCommand(path: string, platform: string): string[] {
  if (isWinPath(path)) {
    return ['explorer.exe', path.replace(/\//g, '\\')]
  }

  return platform === 'Darwin' ? ['open', path] : ['xdg-open', path]
}

/** Why no trash command worked: each command and what it did. Nothing was tried when the platform is unknown. */
export function trashReason(tried: readonly string[], isWin: boolean, platform: string): string {
  if (isWin) {
    return `PowerShell could not move it to the Recycle Bin${tried.length > 0 ? ` (${tried.join('; ')})` : ''}`
  }
  const notFound = tried.length > 0 && tried.every(one => one.endsWith(': not found'))
  const which = tried.length === 0 ? 'no trash command was tried' : tried.join('; ')

  return `${platform === '' ? 'platform unknown, uname gave no answer; ' : ''}${which}${notFound && platform !== 'Darwin' ? '; install gio or trash-cli' : ''}`
}

files.hooks/progress-report.ts:
/** The report_progress replies: how a report, its claimed items and a title are read, and the reply to it. */

import type { Progress } from '../types'
import { cleanText, cutText, cutUnits } from './card-text'
import { hideSecretLines } from './secrets'

/**
 * An agent's report, held to sense: whole steps, at least one planned, never more done than planned.
 * A step line that holds a secret is hidden (UCR-124): the step is drawn and stored. It is hidden
 * before the cut, so a cut cannot leave a part of a secret the check no longer knows.
 */
export function readProgress(input: Record<string, unknown>): Progress | undefined {
  const total = Math.max(1, Math.round(Number(input.total)))
  const done = Math.min(total, Math.max(0, Math.round(Number(input.done))))
  if (!Number.isFinite(total) || !Number.isFinite(done)) {
    return undefined
  }
  const step = typeof input.step === 'string' && input.step.trim() !== '' ? cutUnits(hideSecretLines(input.step.trim()), 120) : undefined

  return step === undefined ? { done, total } : { done, total, step }
}

/**
 * The items an agent claims in a report: up to 20 quoted lines or IDs; undefined when it named none.
 * A claim line that holds a secret is hidden, its ticket IDs kept (UCR-124): claims are stored and
 * echoed in the reply, and an ID is enough to link.
 */
export function readClaims(input: Record<string, unknown>): string[] | undefined {
  if (!Array.isArray(input.items)) {
    return undefined
  }
  const claims = input.items
    .filter((one): one is string => typeof one === 'string' && one.trim() !== '')
    .map(one => cutUnits(hideSecretLines(one.trim()), 300))
    .slice(0, 20)

  return claims.length === 0 ? undefined : claims
}

/** How long a claim stands before the next progress reply asks the agent to confirm it. */
export const CLAIM_CHECK_MS = 10 * 60_000

/**
 * The reply to a progress report. Every 10 minutes it asks the agent to confirm the items it
 * claimed, or, when it claimed none, to name them if its task covers any: about 40 tokens, carried
 * by a call the agent makes anyway.
 */
export function progressReply(claims: readonly string[] | undefined, isDue: boolean): string {
  if (!isDue) {
    return 'Noted.'
  }
  if (claims === undefined || claims.length === 0) {
    return 'Noted. If your task covers items in .claude_todo/, pass them as items in your next report.'
  }

  return `Noted. You said you handle: ${claims.map(claim => `"${cutUnits(claim, 80)}"`).join('; ')}. If that changed, pass the current items in your next report.`
}

/** A headline from the main conversation: a few words, one line, at most TITLE_MAX characters. */
export const TITLE_MAX = 80
export function readTitle(input: unknown): string | undefined {
  const text = typeof input === 'string' ? cutText(cleanText(input.trim().split(/[\r\n]/)[0] ?? '').replace(/[\x7F-\x9F]/g, '').trim(), TITLE_MAX) : ''

  return text === '' ? undefined : text
}

