/** Where the todo folders are: the repo lookup, the global folders that never count, and the folder list. */

import { foldPath, isAbsPath, isCaseOnly, isWinPath, normPath, relIn, resolveAgainst } from './path-forms'

export const DIR = '.claude_todo'
/**
 * The most folders the nearest-folder walk goes up when the session's real path cannot be read
 * (UCR-240). With the real path known, the walk goes up to the file system root, as git does: a
 * session at any depth in a repo finds the repo root's folder (no count limit), and outside a repo
 * the walk ends at the root with no `.git` found. 64 is far past any repo depth seen; a deeper
 * session whose real path also fails to read is taken to be outside a repo.
 */
export const MAX_UP_NO_REAL = 64

/** The file system calls the todo lookup makes, apart from `$` so a test can lay out folders. */
export type TodoFs = {
  exists: (path: string) => Promise<boolean>
  kind: (path: string) => Promise<string | undefined>
  realPath: (path: string) => Promise<string | undefined>
  read: (path: string) => Promise<string>
}

export async function findTodoDirWith(fs: TodoFs): Promise<string | undefined> {
  const found = await repoTodoDir(fs)
  if (found === undefined) {
    return undefined
  }
  const real = await fs.realPath(found)

  return real !== undefined && isGlobalTodo(real) ? undefined : found
}

/**
 * The global todo folders as this machine has them: `$HOME/.claude/.claude_todo` and
 * `$CLAUDE_CONFIG_DIR/.claude_todo`, each as written and as its real path. The text rule below only
 * knows the usual home folders (`/Users`, `/home`, `/root`); a home at `/var/home`, `/var/root`,
 * `/export/home` or anywhere else is known only from the environment.
 */
export const globalDirs = new Set<string>()

/**
 * The folders that hold a global todo folder: `$HOME/.claude` and `$CLAUDE_CONFIG_DIR`, as written. The
 * write check resolves each again at the moment of a write (UCR-148), so a `.claude_todo` made under a
 * symlinked one after the load, or a symlink made after the load, is still known as global.
 */
export const globalParents = new Set<string>()

/** One spelling of a folder for the global compare (UCR-023): slashes folded, no trailing slash, NFC, and a Windows path in any letter case. */
function globalKey(path: string): string {
  const flat = normPath(path)
  const bare = (flat.length > 1 ? flat.replace(/\/+$/, '') : flat).normalize('NFC')

  return isWinPath(bare) ? bare.toLowerCase() : bare
}

/** True when `folder` is the `.claude_todo` of one of `parents` (real paths both), in the spelling the global compare uses (UCR-148). */
export function isTodoOf(folder: string, parents: Iterable<string>): boolean {
  const own = globalKey(folder)

  return [...parents].some(parent => globalKey(`${normPath(parent).replace(/\/+$/, '')}/${DIR}`) === own)
}

/**
 * True when `folder` is `globalReal`, the real path of a global `<parent>/.claude_todo` resolved at the
 * moment of a write, in the spelling the global compare uses (UCR-148): a symlink made at
 * `~/.claude/.claude_todo` itself after the load points it at a project folder, which is then global.
 * Undefined (the global folder does not resolve: there is none) is never a match.
 */
export function isSameTodo(folder: string, globalReal: string | undefined): boolean {
  return globalReal !== undefined && globalKey(globalReal) === globalKey(folder)
}

/**
 * True for the global todo folder, `<home>/.claude/.claude_todo`, which the mod never reads. A project's
 * own `<repo>/.claude/.claude_todo` is not it. On Windows the profile can live anywhere, so every
 * `.claude/.claude_todo` counts as global there.
 */
export function isGlobalTodo(realPath: string): boolean {
  const own = globalKey(realPath)
  if ([...globalDirs].some(dir => globalKey(dir) === own)) {
    return true
  }

  return /^\/(Users|home)\/[^/]+\/\.claude\/\.claude_todo\/?$|^\/root\/\.claude\/\.claude_todo\/?$/.test(realPath) || /^[A-Za-z]:[\\/](.*[\\/])?\.claude[\\/]\.claude_todo[\\/]?$/i.test(realPath)
}

/**
 * The main checkout named by a linked worktree's git dir, by git's own rule (UCR-202; `gitFileWhere`
 * follows it too): a git dir with a `commondir` file is a linked worktree's, and its common dir is that
 * file's path read against the git dir. A git dir with none is the common dir itself: no linked
 * worktree, so no other main checkout. The text `/worktrees/` in a path tells nothing: a separate git
 * dir at `~/worktrees/x.git`, or a submodule at `worktrees/foo`, has it too.
 *
 * A common dir `<main>/.git` gives `<main>`. A separate git dir (`/elsewhere/repo.git`, also a
 * submodule's) has no `.git` folder in the main checkout, so its `core.worktree` setting is read
 * instead. A relative `gitdir` (git 2.48 `worktree.useRelativePaths`) reads against `base`, the
 * folder of the `.git` file as a path from the session folder.
 */
async function mainOf(fs: TodoFs, gitdir: string | undefined, base: string): Promise<string | undefined> {
  if (gitdir === undefined || gitdir === '') {
    return undefined
  }
  const dir = isAbsPath(gitdir) ? foldPath(gitdir) : foldPath(`${base}${gitdir}`)
  const named = (await fs.read(`${dir}/commondir`).catch(() => '')).split('\n')[0]?.replace(/\r$/, '').trim() ?? ''
  if (named === '') {
    return undefined
  }
  const common = foldPath(isAbsPath(named) ? named : `${dir}/${named}`)
  if (common.endsWith('/.git')) {
    // A main checkout at the file system root gives '', which the caller joins as `/.claude_todo`.
    return common.slice(0, -'/.git'.length)
  }
  if (common === '.git') {
    return '.'
  }
  const set = /^\s*worktree\s*=\s*(.+)$/m.exec(await fs.read(`${common}/config`).catch(() => ''))?.[1]?.trim()

  return set === undefined || set === '' ? undefined : foldPath(isAbsPath(set) ? set : `${common}/${set}`)
}

/**
 * The nearest `.claude_todo/`, from the session folder up to the repo root: a subfolder with a todo
 * of its own keeps it. With none up to the root, a worktree uses its main checkout's. Outside a
 * repo, only the session folder's own counts.
 *
 * Which folder a linked worktree writes is decided in discovery (`centralRoot`, UCR-104); this walk
 * only finds the nearest folder. With no `.claude_todo/` up to the worktree's root, a worktree uses its
 * main checkout's, named by `mainOf`.
 *
 * The walk has no count limit (UCR-240): it goes up to the file system root (the segment count of the
 * session's real path), so a repo's root is found at any depth, as git finds it. Only when that real
 * path cannot be read does MAX_UP_NO_REAL bound it.
 */
async function repoTodoDir(fs: TodoFs): Promise<string | undefined> {
  let maxUp: number | undefined
  // Read once, after the first check: the folders from the session folder up to the file system root.
  const levels = async (): Promise<number> => {
    if (maxUp === undefined) {
      const real = await fs.realPath('.').catch(() => undefined)
      maxUp = real === undefined || !isAbsPath(real) ? MAX_UP_NO_REAL : normPath(real).split('/').filter(part => part !== '').length
    }

    return maxUp
  }
  for (let depth = 0; depth === 0 || depth <= (await levels()); depth += 1) {
    const prefix = '../'.repeat(depth)
    if (await fs.exists(`${prefix}${DIR}`)) {
      // Taken only inside a repo: the walk must reach a .git at or above this folder.
      for (let up = depth; up <= (await levels()); up += 1) {
        if (await fs.exists(`${'../'.repeat(up)}.git`)) {
          return `${prefix}${DIR}`
        }
      }

      return depth === 0 ? DIR : undefined
    }
    const git = `${prefix}.git`
    if (!(await fs.exists(git))) {
      continue
    }
    if ((await fs.kind(git)) === 'file') {
      const gitdir = /^gitdir:\s*(.+)$/m.exec(await fs.read(git))?.[1]?.replace(/\r$/, '').trim()
      const main = await mainOf(fs, gitdir, prefix)

      return main !== undefined && (await fs.exists(`${main}/${DIR}`)) ? `${main}/${DIR}` : undefined
    }

    return undefined
  }

  return undefined
}

/** One `.claude_todo/` folder: `path` as the engine's fs takes it, `rel` from its checkout's root. */
export type TodoFolder = { path: string; rel: string; isOther: boolean; real?: string }

/** Most folders the pane reads: a repo with more is cut, primary folder first, then by path. */
export const MAX_FOLDERS = 20

/**
 * The `.claude_todo/` folders in the output of `git ls-files -z`: every entry with a `.claude_todo`
 * segment is cut to the folder path ending there. An ignored folder lists as a collapsed directory
 * entry (`x/.claude_todo/`), which cuts the same way. Duplicates drop; the order is by path.
 *
 * The segment matches in any letter case (UCR-151): after a case-only rename of the folder itself on a
 * disk that ignores case, git keeps the index spelling (`.Claude_todo`) while the disk has
 * `.claude_todo`. Discovery then reads each folder in the disk's spelling (`diskSpelling`) and keeps only
 * one spelled `.claude_todo` there (`isMisspelledTodo` names the rest once).
 */
export function todoFoldersIn(listing: string, root: string): { path: string; rel: string }[] {
  const rels = new Set<string>()
  for (const entry of listing.split('\0')) {
    const parts = entry.split('/').filter(part => part !== '')
    const at = parts.findIndex(part => part.toLowerCase() === DIR)
    if (at >= 0) {
      rels.add(parts.slice(0, at + 1).join('/'))
    }
  }

  return [...rels].sort().map(rel => ({ path: `${root}/${rel}`, rel }))
}

/**
 * A listed folder in the disk's spelling (UCR-151): when its real path differs from the listed path
 * only by letter case (git keeps the index spelling after a case-only rename), the real path, with
 * `rel` from whichever of `roots` holds it. Any other real path (a symlink, NFD) leaves it as listed,
 * for the trust check to judge.
 */
export function diskSpelling(one: { path: string; rel: string }, real: string | undefined, roots: readonly string[]): { path: string; rel: string } {
  if (real === undefined || !isCaseOnly(one.path, real)) {
    return one
  }
  // A Windows real path may come with backslashes: the path the mod writes keeps forward slashes, as git's does.
  const path = normPath(real)
  const rel = roots.map(root => relIn(path, normPath(root))).find(found => found !== undefined)

  return { path, rel: rel ?? one.rel }
}

/**
 * True for a folder path whose last segment is `.claude_todo` in another letter case only (UCR-151):
 * `.Claude_todo` on the disk, or as git lists it on a disk that keeps case apart. The mod reads and
 * writes only `.claude_todo`, so discovery leaves such a folder out and says so once.
 */
export function isMisspelledTodo(path: string): boolean {
  const last = normPath(path).replace(/\/+$/, '').split('/').pop() ?? ''

  return last !== DIR && last.toLowerCase() === DIR
}

/**
 * One line of git output without its line break only (UCR-100): a folder name may end in a space, so
 * `trim` would give another folder. A CR from a Windows git goes with the line break.
 */
function lineOf(line: string): string {
  return line.replace(/\r$/, '')
}

/** The arguments of the one `git rev-parse` call that `repoRoots` and `sessionFolder` read, in the order git prints them. */
export const REV_PARSE = ['git', 'rev-parse', '--show-toplevel', '--git-dir', '--git-common-dir', '--show-prefix']

/**
 * The lines of the REV_PARSE output, or undefined when there are more than its four values and the
 * last line break give (UCR-150): a line break in a path (a folder named `nl<LF>x`) moves every line,
 * so the first would name another folder. Such output is never read; the caller then takes the
 * outside-a-repo path. Git prints each of the four values on a line of its own, so every line break
 * in a path shows as an extra line. Output of the right shape can still name another folder (GIT_DIR
 * and GIT_WORK_TREE in the environment, a core.worktree set elsewhere): discovery checks the session
 * folder against the real path of `.` for that (`isSameFolder`, UCR-150).
 */
export function revParseLines(stdout: string): string[] | undefined {
  // A CR goes with the line break only when every line break is CRLF (a Windows git): a POSIX folder name may end in a CR, and cut there it names another folder (UCR-150).
  const isCrlf = !/(^|[^\r])\n/.test(stdout)
  const lines = stdout.split('\n').map(line => (isCrlf ? lineOf(line) : line))

  // One line per value REV_PARSE asks for (its arguments past `git rev-parse`), and the empty one after the last line break.
  return lines.length > REV_PARSE.length - 2 + 1 ? undefined : lines
}

/**
 * The session folder as git sees it: the top folder joined with `--show-prefix` (the fourth line of
 * the REV_PARSE output; empty at the top). Undefined when the output has no top folder.
 */
export function sessionFolder(stdout: string): string | undefined {
  const lines = revParseLines(stdout)
  if (lines === undefined) {
    return undefined
  }
  const top = lines[0] ?? ''

  return isAbsPath(top) ? resolveAgainst(top, lines[3] ?? '') : undefined
}

/**
 * The main checkout as the first entry of `git worktree list --porcelain`. Not when that entry is the
 * common dir itself or inside it, or is marked `bare`: for a separate git dir git lists the git dir
 * there, which is no checkout (UCR-057).
 */
function listedMain(worktrees: string, common: string): string | undefined {
  const block = worktrees.split(/\n\s*\n/)[0] ?? ''
  const listed = /^worktree (.+)$/m.exec(block)?.[1]?.replace(/\r$/, '')
  if (listed === undefined || !isAbsPath(listed) || /^bare$/m.test(block)) {
    return undefined
  }
  const main = listed.replace(/\/+$/, '')

  return main === common || main.startsWith(`${common}/`) ? undefined : main
}

/**
 * The git common dir as an absolute path, from the REV_PARSE output (the third line; the second in the
 * old two-line output), read against the session folder as `repoRoots` reads it. In every git layout it
 * is a directory: `<root>/.git`, a separate git dir, a submodule's `.git/modules/<name>`, and the main
 * one for a linked worktree (UCR-030). Undefined when the output names none.
 */
export function gitCommonDir(stdout: string): string | undefined {
  const lines = revParseLines(stdout) ?? []
  const here = sessionFolder(stdout)
  const common = ((lines[2] ?? '') !== '' ? lines[2] : lines[1]) ?? ''

  return here === undefined || common === '' ? undefined : resolveAgainst(here, common)
}

/**
 * The repo root and, from a linked git worktree, its main checkout, from the REV_PARSE output (no
 * `--path-format`, which git before 2.31 does not know). Git prints a relative dir against the
 * folder it runs in, not the top: from `sub/deep` the common dir is `../../.git` (UCR-085). So each
 * relative dir is read against the session folder (top plus the `--show-prefix` line); output with
 * no prefix line is read against the top.
 *
 * A worktree is linked only when its git dir is `<common dir>/worktrees/<name>`, the one place git
 * keeps a linked worktree's git dir. Any other pair of differing dirs gives `isLinked` with no main,
 * so a misread dir can never make an ancestor folder the main checkout. The main checkout is the first
 * entry of `git worktree list --porcelain` (`worktrees`) when that entry is a checkout; without the
 * list, the folder that holds a common dir named `.git`. A linked worktree with no main found is
 * `isLinked`, so the caller can keep the tidy buttons off. The old two-line output (top, common) still reads.
 */
export function repoRoots(stdout: string, worktrees = ''): { root: string; main?: string; isLinked?: true } | undefined {
  const lines = revParseLines(stdout) ?? []
  const top = lines[0]
  const here = sessionFolder(stdout)
  if (top === undefined || here === undefined) {
    return undefined
  }
  const hasDir = (lines[2] ?? '') !== ''
  const common = (hasDir ? lines[2] : lines[1]) ?? ''
  if (common === '') {
    return { root: top }
  }
  const absCommon = resolveAgainst(here, common)
  if (hasDir) {
    const gitDir = resolveAgainst(here, lines[1]!)
    if (gitDir === absCommon) {
      return { root: top }
    }
    if (!gitDir.startsWith(`${absCommon}/worktrees/`)) {
      // The repo's own `.git` entry is a symlink: git prints the git dir as its real path and the common dir as the link (UCR-099). No linked worktree has the top's own `.git` as its common dir.
      return absCommon === `${top}/.git` ? { root: top } : { root: top, isLinked: true }
    }
  } else if (absCommon === `${top}/.git` || !absCommon.endsWith('/.git')) {
    return { root: top }
  }
  const main = listedMain(worktrees, absCommon) ?? (absCommon.endsWith('/.git') ? absCommon.slice(0, -'/.git'.length) : undefined)

  return main === undefined || main === '' || main === top ? { root: top, isLinked: true } : { root: top, main }
}

/**
 * The folders the pane reads from those found: the global ones dropped, a place found twice kept
 * once (the primary's entry when it is one of them, else the first), the primary folder first and
 * the rest by path, cut to MAX_FOLDERS. `primary` is the `path` of the one folder the nearest-up
 * rule picks.
 */
export function pickFolders(found: readonly { path: string; rel: string; real?: string }[], primary: string | undefined, globals: ReadonlySet<string>, limit = MAX_FOLDERS): TodoFolder[] {
  const byRel = new Map<string, { path: string; rel: string; real?: string }>()
  for (const one of found) {
    if (globals.has(one.path)) {
      continue
    }
    const held = byRel.get(one.rel)
    if (held === undefined || (one.path === primary && held.path !== primary)) {
      byRel.set(one.rel, one)
    }
  }
  const kept = [...byRel.values()]
  const first = kept.filter(one => one.path === primary)
  const rest = kept.filter(one => one.path !== primary).sort((a, b) => (a.rel < b.rel ? -1 : a.rel > b.rel ? 1 : 0))

  return [...first.map(one => ({ ...one, isOther: false })), ...rest.map(one => ({ ...one, isOther: true }))].slice(0, limit)
}

/** Where a folder sits in its checkout, for the heading in the central file: its path without `.claude_todo`. */
export function placeOf(rel: string): string {
  const place = rel.slice(0, Math.max(0, rel.length - DIR.length)).replace(/\/$/, '')

  return place === '' ? 'the root of another checkout' : place
}

/** A folder's place in its checkout, for telling same-named files apart: its path without `.claude_todo`; empty at the repo root. */
export function folderPlace(rel: string): string {
  return rel.slice(0, Math.max(0, rel.length - DIR.length)).replace(/\/$/, '')
}

files.hooks/row-equality.ts:
/** Value equality of agent rows, so a change that changes nothing is not counted. */

import type { AgentRow } from '../types'

/** Value equality for the plain data of a row: primitives, arrays and flat objects. */
function sameValue(a: unknown, b: unknown): boolean {
  if (a === b) {
    return true
  }
  if (typeof a !== 'object' || typeof b !== 'object' || a === null || b === null) {
    return false
  }
  if (Array.isArray(a) || Array.isArray(b)) {
    return Array.isArray(a) && Array.isArray(b) && a.length === b.length && a.every((one, i) => sameValue(one, b[i]))
  }
  const x = a as Record<string, unknown>
  const y = b as Record<string, unknown>

  return [...new Set([...Object.keys(x), ...Object.keys(y)])].every(key => sameValue(x[key], y[key]))
}

/**
 * True when both lists hold equal rows in the same order. No JSON: the tick calls it. A row's object
 * fields (such as `progress`) allocate a small key list each (UCR-133): a row holds few such fields,
 * so the cost stays small.
 */
export function sameRows(a: readonly AgentRow[], b: readonly AgentRow[]): boolean {
  return a === b || (a.length === b.length && a.every((row, i) => sameValue(row, b[i])))
}

files.hooks/series.ts:
/** The top card's data: the agent and token series over the window, and the axes they plot on. */

import type { Usage } from './card-types'

/** A sample: [time in ms, value]. */
export type Point = readonly [number, number]

/**
 * What the top card plots, kept per session in the store: live agents (a point at each change of
 * the count), all tokens since the last compaction (main loop and agents, a point at each model
 * request, see addStep), and the times of the compactions. Agent points older than the window are
 * dropped, except the last one before it; token points are kept one RATE_MS longer, so the
 * tokens per minute at the left edge still has its minute (UCR-113). The tokens-per-minute trace
 * is worked out from the token points (tokenRate), so it is not stored. `seeds` are the times of
 * token points set from the kept count after a load (seedSeries), whose rise is no usage.
 */
export type Series = { agents: Point[]; tokens: Point[]; compacts: number[]; seeds?: number[] }

/** The time axis spans the last 30 minutes. */
export const WINDOW_MS = 30 * 60_000
/** Most points kept per series. */
export const SERIES_CAP = 2000
/** The tokens-per-minute trace counts the tokens of the minute before each QUANT_MS step. */
export const RATE_MS = 60_000

/** X positions snap to this step, so a redraw between steps sends the same markup. */
export const QUANT_MS = 30_000

export const emptySeries = (): Series => ({ agents: [], tokens: [], compacts: [] })

/** Drops points older than `keepMs` (the window), keeping the last one before it so the line starts at the left edge. */
export function trimPoints(points: readonly Point[], now: number, keepMs = WINDOW_MS): Point[] {
  const from = now - keepMs
  const first = points.findIndex(point => point[0] >= from)
  const start = first === -1 ? Math.max(0, points.length - 1) : Math.max(0, first - 1)

  return points.slice(start).slice(-SERIES_CAP)
}

/**
 * The blip rule (UCR-195): a new time more than one QUANT_MS behind the last point is not a small
 * step back but a clock that once read far ahead. The points later than the new time are then
 * re-timed to it, with their values kept, so the series follows the clock again from here. A
 * smaller step back keeps the clamp of UCR-158 (the new point goes at the last point's time).
 * This moves one list of points only; retimeSeries moves the compactions and seeds with them, so
 * a seeded point keeps its seed mark (UCR-215).
 */
export function retimeTail(points: readonly Point[], at: number): readonly Point[] {
  const last = points[points.length - 1]
  if (last === undefined || last[0] - at <= QUANT_MS) {
    return points
  }

  return points.map((point): Point => (point[0] > at ? [at, point[1]] : point))
}

/**
 * The time a trim may cut to (UCR-212): the new time, but never more than one QUANT_MS past the
 * last point already held (the last trusted time). A clock that reads far ahead once (a blip) then
 * trims nothing; the next real read re-times the blip point (retimeTail) and trims as usual. A real
 * gap (an idle hour) is trimmed at the request after it, one point later.
 */
export function trustedTime(points: readonly Point[], at: number): number {
  const last = points[points.length - 1]

  return last === undefined ? at : Math.min(at, last[0] + QUANT_MS)
}

/** Adds a point when the value changed (or the series is empty), then trims to `keepMs`. */
export function addPoint(all: readonly Point[], rawAt: number, value: number, keepMs = WINDOW_MS): Point[] {
  const points = retimeTail(all, rawAt)
  const last = points[points.length - 1]
  // Points stay in time order: a clock that stepped back adds its point at the last point's time (UCR-158).
  const at = last === undefined ? rawAt : Math.max(rawAt, last[0])
  const trim = trustedTime(points, at)
  if (last !== undefined && last[1] === value) {
    return trimPoints(points, trim, keepMs)
  }

  return trimPoints([...points, [at, value]], trim, keepMs)
}

/**
 * Adds one live-agent count. A change in the same QUANT_MS step as the last point replaces that
 * point (the step keeps its last value), as the plot snaps x to the step anyway: a count that
 * flips every second would else fill SERIES_CAP and push the start of the window out (UCR-162).
 * The series' first point is never replaced, so the line keeps its start; a replacement that
 * returns to the value before it leaves no point.
 */
export function addAgentPoint(all: readonly Point[], at: number, value: number): Point[] {
  const points = retimeTail(all, at)
  const last = points[points.length - 1]
  const prev = points[points.length - 2]
  if (last !== undefined && prev !== undefined && last[1] !== value && Math.floor(last[0] / QUANT_MS) === Math.floor(Math.max(at, last[0]) / QUANT_MS)) {
    return addPoint(points.slice(0, -1), at, value)
  }

  return addPoint(points, at, value)
}

/** How long token points are kept: the window and the minute the first tokens-per-minute step sums. */
const TOKEN_KEEP_MS = WINDOW_MS + RATE_MS

/**
 * Adds one model request's count to the token series. A request in the same QUANT_MS step as the
 * last point, when that point was a rise, moves that point up instead of adding one: the plot
 * snaps x to QUANT_MS anyway, the rises in each step still sum to the tokens of that step (so
 * tokenRate is exact), and a busy session keeps about two points a step, far under SERIES_CAP,
 * where one point per request would push the start of the window out of the cap.
 */
export function addStep(all: readonly Point[], rawAt: number, value: number, seeds: readonly number[] = [], used = 0): Point[] {
  const points = retimeTail(all, rawAt)
  if (points.length === 0 && seeds.length === 0 && used > 0 && value > 0) {
    // The first request of a fresh series: a base point under it, so its rise counts as usage (UCR-157).
    return addStep([[rawAt, Math.max(0, value - used)]], rawAt, value, seeds)
  }
  const last0 = points[points.length - 1]
  const at = last0 === undefined ? rawAt : Math.max(rawAt, last0[0])
  const last = points[points.length - 1]
  const prev = points[points.length - 2]
  // A seeded point is never moved: its time marks its rise as no usage (seedSeries).
  if (last !== undefined && prev !== undefined && last[1] > prev[1] && value >= last[1] && Math.floor(last[0] / QUANT_MS) === Math.floor(at / QUANT_MS) && !seeds.includes(last[0])) {
    return trimPoints([...points.slice(0, -1), [at, value]], trustedTime(points, at), TOKEN_KEEP_MS)
  }

  return addPoint(points, at, value, TOKEN_KEEP_MS)
}

/**
 * Tokens per minute over the window, from the token series: at each QUANT_MS step `t`, the sum of
 * the rises with a time in [t - RATE_MS, t). A fall (a compaction) is no usage, the first point
 * has no rise, and the rise into the first point at a `seeds` time is no usage, so a value seeded from the
 * kept count after a load is never counted as usage. The steps start where the data starts (the
 * left edge at the latest) and end at `now` snapped down, so the trace, like the rest of the card,
 * changes only with the data and each QUANT_MS step.
 */
export function tokenRate(points: readonly Point[], now: number, seeds: readonly number[] = []): Point[] {
  const first = points[0]
  if (first === undefined) {
    return []
  }
  const end = Math.floor(now / QUANT_MS) * QUANT_MS
  const rises: Point[] = []
  for (let i = 1; i < points.length; i += 1) {
    const rise = points[i]![1] - points[i - 1]![1]
    // The seed is the first point at its time; a request counted at that same ms comes after it.
    const isSeed = seeds.includes(points[i]![0]) && points[i - 1]![0] !== points[i]![0]
    if (rise > 0 && !isSeed) {
      rises.push([points[i]![0], rise])
    }
  }
  const out: Point[] = []
  for (let t = Math.max(end - WINDOW_MS, Math.ceil(first[0] / QUANT_MS) * QUANT_MS); t <= end; t += QUANT_MS) {
    out.push([t, rises.reduce((sum, rise) => (rise[0] >= t - RATE_MS && rise[0] < t ? sum + rise[1] : sum), 0)])
  }

  return out
}

/**
 * The series after a load, so the trace ends at the kept count since the last compaction, the
 * value the mod holds. The count is stored at each model request and the series only with a
 * redraw (UCR-084), so the kept series can lag the kept count:
 * - a series with no token point gets one point at `now` with the kept count;
 * - a kept compaction inside the window, missing from the series and after its last token point,
 *   gets its marker, and its fall to zero when the series has token points;
 * - a series whose last token value is under the kept count gets a point at `now` with the count.
 * Each point added at `now` is a seed: tokenRate counts its rise as no usage, so the gap draws no
 * false tokens-per-minute spike. A series at or above the kept count is returned as it is.
 */
export function seedSeries(series: Series, usage: Usage | undefined, now: number): Series {
  if (usage === undefined) {
    return series
  }
  const kept = Math.max(0, usage.tokens - (usage.atCompact ?? 0))
  const at = usage.compactAt
  const lastAt = series.tokens[series.tokens.length - 1]?.[0] ?? -Infinity
  const isMarked = at !== undefined && at >= now - WINDOW_MS && at <= now && !series.compacts.includes(at) && at > lastAt
  // The fall to zero only after points of the segment before it; an empty series gets the marker alone.
  const fall: Point[] = series.tokens.length > 0 && at !== undefined ? [[at, 0]] : []
  const marked = isMarked ? { ...series, tokens: [...series.tokens, ...fall], compacts: [...series.compacts, at].sort((a, b) => a - b) } : series
  const last = marked.tokens[marked.tokens.length - 1]
  if (last !== undefined && last[1] >= kept) {
    return marked
  }
  // After the last point, never at its time: the seed must be the first point at its time.
  const time = last !== undefined && last[0] >= now ? last[0] + 1 : now

  return { ...marked, tokens: [...marked.tokens, [time, kept]], seeds: [...(series.seeds ?? []), time] }
}

/**
 * The whole series re-timed by the blip rule of retimeTail (UCR-195, UCR-215): when the latest
 * time it holds (a token or agent point, a compaction, a seed) is more than one QUANT_MS past `at`,
 * every token point, agent point, compaction and seed later than `at` moves to `at`. So a
 * compaction mark moves back with its fall, and a seed with its point, and the seed's rise stays
 * no usage. The seed must stay the first point at its time (tokenRate): the re-timed token points
 * before the last seeded one go (their rises are inside the seed's, which the kept count already
 * holds), and the run goes 1 ms after `at` when a kept point sits at `at` already. A series that is
 * not ahead is returned as it is.
 */
export function retimeSeries(series: Series, at: number): Series {
  const seeds = series.seeds ?? []
  const lastOf = (points: readonly Point[]) => points[points.length - 1]?.[0] ?? -Infinity
  const latest = Math.max(lastOf(series.tokens), lastOf(series.agents), ...series.compacts, ...seeds)
  if (!(latest - at > QUANT_MS)) {
    return series
  }
  const kept = series.tokens.filter(point => point[0] <= at)
  let run = series.tokens.filter(point => point[0] > at)
  let seedAt: number | undefined
  let seedIndex = -1
  run.forEach((point, i) => {
    if (seeds.includes(point[0])) {
      seedIndex = i
    }
  })
  let time = at
  if (seedIndex >= 0) {
    run = run.slice(seedIndex)
    time = kept[kept.length - 1]?.[0] === at ? at + 1 : at
    seedAt = time
  }
  const tokens = [...kept, ...run.map((point): Point => [time, point[1]])]
  const compacts = [...new Set(series.compacts.map(one => Math.min(one, at)))].sort((a, b) => a - b)
  const nextSeeds = [...seeds.filter(one => one <= at), ...(seedAt === undefined ? [] : [seedAt])]
  return {
    agents: series.agents.map((point): Point => (point[0] > at ? [at, point[1]] : point)),
    tokens,
    compacts,
    ...(nextSeeds.length > 0 ? { seeds: nextSeeds } : {}),
  }
}

/** One model request's count, on the whole series: re-timed first (retimeSeries), then addStep with the series' seeds. */
export function addTokens(series: Series, rawAt: number, value: number, used = 0): Series {
  const timed = retimeSeries(series, rawAt)

  return { ...timed, tokens: addStep(timed.tokens, rawAt, value, timed.seeds, used) }
}

/** One live-agent count, on the whole series: re-timed first (retimeSeries), then addAgentPoint. */
export function addAgents(series: Series, rawAt: number, value: number): Series {
  const timed = retimeSeries(series, rawAt)

  return { ...timed, agents: addAgentPoint(timed.agents, rawAt, value) }
}

/** Records a compaction: the marker, and the token line falling to zero. */
export function addCompact(series: Series, rawAt: number): Series {
  // Clamped like addStep (UCR-158): a compaction behind the last token point goes at its time; a far-behind one re-times the series (UCR-195, UCR-215).
  const timed = retimeSeries(series, rawAt)
  const tokens = retimeTail(timed.tokens, rawAt)
  const last = tokens[tokens.length - 1]
  const at = last === undefined ? rawAt : Math.max(rawAt, last[0])
  const trim = trustedTime(tokens, at)
  const from = trim - WINDOW_MS
  // A compaction already at this time is not added again (UCR-216): two marks on one x would draw two dashed lines.
  const compacts = timed.compacts.map(one => Math.min(one, at)).filter(one => one >= from)

  return { ...timed, tokens: trimPoints([...tokens, [at, 0]], trim, TOKEN_KEEP_MS), compacts: [...new Set([...compacts, at])].slice(-SERIES_CAP) }
}

/**
 * Reads a stored series back, keeping only well-formed points: finite, not negative, not later than
 * `now` plus one QUANT_MS step (a clock that ran ahead), sorted by time (the sort is stable, so
 * points at one time keep their order). Compaction times and seeds need the same bounds (UCR-158).
 */
export function readKeptSeries(stored: unknown, now = Infinity): Series {
  const out = emptySeries()
  if (typeof stored !== 'object' || stored === null) {
    return out
  }
  const raw = stored as Partial<Record<keyof Series, unknown>>
  const limit = now + QUANT_MS
  const points = (list: unknown): Point[] =>
    Array.isArray(list)
      ? list
          .filter((one): one is [number, number] => Array.isArray(one) && one.length === 2 && Number.isFinite(one[0]) && Number.isFinite(one[1]) && one[0] <= limit && one[1] >= 0)
          .sort((a, b) => a[0] - b[0])
          .slice(-SERIES_CAP)
      : []
  out.agents = points(raw.agents)
  out.tokens = points(raw.tokens)
  // One compaction a time (UCR-216).
  out.compacts = Array.isArray(raw.compacts) ? [...new Set(raw.compacts.filter((one): one is number => Number.isFinite(one) && one <= limit))].sort((a, b) => a - b).slice(-SERIES_CAP) : []
  // Seeds older than the first token point mark no point any more; a seed past the limit is a clock that ran ahead, as for points (UCR-216).
  const first = out.tokens[0]?.[0] ?? Infinity
  const seeds = Array.isArray(raw.seeds) ? raw.seeds.filter((one): one is number => Number.isFinite(one) && one >= first && one <= limit).slice(-SERIES_CAP) : []
  if (seeds.length > 0) {
    out.seeds = seeds
  }

  return out
}

/** One axis: its top value. */
export type AxisState = { max: number }
export type Axes = { agents: AxisState; tokens: AxisState; rate: AxisState }
type AxisKind = 'agents' | 'tokens'

/** The nth nice top: agents 4, 6, 8, 12, 16, 24, 32...; tokens 150k, 300k, 600k, 900k, 1.5M, 3M, 6M, 9M, 15M... */
function niceAt(kind: AxisKind, k: number): number {
  return kind === 'agents'
    ? (k % 2 === 0 ? 4 : 6) * 2 ** Math.floor(k / 2)
    : Math.round([1.5, 3, 6, 9][k % 4]! * 10 ** (5 + Math.floor(k / 4)))
}

/** The smallest nice axis top that holds `peak`. */
export function niceMax(kind: AxisKind, peak: number): number {
  // A peak that is not a number (UCR-155) draws the base step, never the last of 200.
  if (!Number.isFinite(peak)) {
    return niceAt(kind, 0)
  }
  for (let k = 0; k < 200; k += 1) {
    const value = niceAt(kind, k)
    if (value >= peak) {
      return value
    }
  }

  return niceAt(kind, 199)
}

/**
 * The next state of one axis: it grows when the peak would leave the plot, to the next nice step;
 * it shrinks, to the step that holds the peak, when the peak is under half the axis (#T0049). The
 * peak is the top of the whole window, so a shrink needs every visible value under half: it never
 * flaps, and a high value (the count before a compaction) lets go the moment it leaves the window.
 * Otherwise it stays.
 */
export function stepAxis(prev: AxisState | undefined, kind: AxisKind, peak: number): AxisState {
  if (prev === undefined || peak > prev.max || peak < prev.max / 2) {
    return { max: niceMax(kind, peak) }
  }

  return { max: prev.max }
}

/** The points on the plot: those in the window, and the one before it moved to the left edge. */
export function windowed(points: readonly Point[], from: number): Point[] {
  const inside = points.filter(point => point[0] >= from)
  const before = points.filter(point => point[0] < from).pop()

  return before === undefined ? inside : [[from, before[1]], ...inside]
}

/**
 * The points to draw: the first, then the last point of each QUANT_MS step (UCR-217). The series
 * coalesces each step to about one point already (addStep, addAgentPoint), so a live series draws
 * as it is held; a stored series of an older build, up to SERIES_CAP points, draws its steps only,
 * and the end labels place over about 60 segments a trace, not 2000 (358 ms a draw before).
 */
export function onePerStep(points: readonly Point[]): Point[] {
  const out: Point[] = []
  for (const point of points) {
    const prev = out[out.length - 1]
    if (out.length > 1 && prev !== undefined && Math.floor(prev[0] / QUANT_MS) === Math.floor(point[0] / QUANT_MS)) {
      out[out.length - 1] = point
    } else {
      out.push(point)
    }
  }

  return out
}

/**
 * The token points the token axis must hold (#T004A): those from the last compaction in the
 * window on, or all of them when no compaction is in the window.
 */
export function sinceCompact(series: Series, from: number): Point[] {
  const last = series.compacts.filter(one => one >= from).pop()

  return last === undefined ? series.tokens : series.tokens.filter(point => point[0] >= last)
}

/** Steps the three axes for the series as of `now`. */
export function stepAxes(prev: Axes | undefined, series: Series, now: number): Axes {
  const from = Math.floor(now / QUANT_MS) * QUANT_MS - WINDOW_MS
  const peak = (points: readonly Point[]) => windowed(points, from).reduce((top, point) => Math.max(top, point[1]), 0)

  // The token axis holds the count from the last compaction in the window on (#T004A): the count
  // before it is drawn clipped at the top, so it never flattens the count since.
  // The tokens per minute have their own axis, on the same gridlines (#T004E): tied to the count,
  // the rate drew flat along the bottom once the count reached hundreds of millions. The rate does
  // not reset at a compaction, so the whole window of it is held.
  const tokenPeak = peak(sinceCompact(series, from))
  const ratePeak = peak(tokenRate(series.tokens, now, series.seeds))

  return {
    agents: stepAxis(prev?.agents, 'agents', peak(series.agents)),
    tokens: stepAxis(prev?.tokens, 'tokens', tokenPeak),
    rate: stepAxis(prev?.rate, 'tokens', ratePeak),
  }
}

