/** The todo cards: ticket cards, file cards, the board header, and the space a ticket leaves. */

import { agentColor, agentLabel, ORCH } from './agent-identity'
import { actor, badge, badgeWidth, isBlinking, moreDisk, ownerDot, ownersFit, strip } from './card-parts'
import { ACCENT, Blinks, CARD, FAINT, INNER, LABEL, LIGHT_CSS, PAD, PANE, RULE, stage, STAGE_GRAY, SUB, SUGGESTED, W } from './card-stage'
import { cutText, esc, fit, MAX_LINES, wrap } from './card-text'
import type { Card, FileView, ItemStatus, ItemView, View } from './card-types'

function itemMark(x: number, y: number, status: ItemStatus, owners: readonly number[], view: View, blinks: Blinks): string {
  if (status === 'completed') {
    return `<path d="M ${x - 4} ${y} l 2.8 2.8 l 5.2 -5.6" fill="none" stroke="#FFFFFF" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/>`
  }
  if (owners.length > 0) {
    return ownerDot(x, y, 5, owners, view, blinks)
  }
  if (status === 'in_progress') {
    return `<circle cx="${x}" cy="${y}" r="4" fill="${STAGE_GRAY}"/>`
  }

  return `<circle cx="${x}" cy="${y}" r="4.5" fill="none" stroke="${FAINT}" stroke-width="1.2"/>`
}

const ITEMS_PER_CARD = 40
const LINE_H = 18

/**
 * One ticket as a Stage UI card, `width` px wide: a 12 px container on the tonal card fill; a top
 * row with the status mark, an ID chip, a category chip and a status badge; the item's text, up to
 * 4 lines; and the agents on it as colored chips. In progress draws a violet accent bar (progress,
 * COL-1); a ticket an agent works on draws its border and bar in the agent's color instead. When
 * `actions` (a count), a bottom row of its own is kept free for the pane's buttons and their tips.
 */
export function ticketSvg(item: ItemView, view: View, width: number, info: { id?: string; category?: string; isSent: boolean; actions?: number }): Card {
  const w = Math.max(200, Math.round(width))
  const pad = 14
  const blinks = new Blinks()
  const owner = item.owners[0]
  const accent = owner !== undefined ? agentColor(owner) : item.status === 'in_progress' ? ACCENT : undefined
  const parts: string[] = []
  let x = pad
  const top = 22
  // Status mark
  if (item.status === 'completed') {
    parts.push(`<path d="M ${x} ${top - 1} l 2.8 2.8 l 5.2 -5.6" fill="none" stroke="#FFFFFF" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/>`)
  } else if (owner !== undefined) {
    parts.push(ownerDot(x + 4, top - 3, 4.5, item.owners, view, blinks))
  } else if (item.status === 'in_progress') {
    parts.push(`<circle cx="${x + 4}" cy="${top - 3}" r="4" fill="${STAGE_GRAY}"/>`)
  } else {
    parts.push(`<circle cx="${x + 4}" cy="${top - 3}" r="4.5" fill="none" stroke="${FAINT}" stroke-width="1.2"/>`)
  }
  x += 16
  // Status badge, right
  const status = info.isSent && item.status !== 'completed' ? { label: 'Sent', kind: 'neutral' as const } : item.status === 'completed' ? { label: 'Done', kind: 'ok' as const } : item.status === 'in_progress' ? { label: 'In progress', kind: 'live' as const } : item.status === 'queued' ? { label: 'Queued', kind: 'neutral' as const } : { label: 'Open', kind: 'neutral' as const }
  const badgeRight = w - pad
  parts.push(badge(badgeRight, top + 2, status.label, status.kind))
  const room = badgeRight - badgeWidth(status.label) - 8
  // ID chip
  if (info.id !== undefined && x + 40 < room) {
    const cw = Math.round(info.id.length * 7 + 14)
    parts.push(`<rect x="${x}" y="${top - 13}" width="${cw}" height="20" rx="8" fill="rgba(255,255,255,.1)"/>
<text x="${x + cw / 2}" y="${top + 1}" text-anchor="middle" fill="${LABEL}" font-size="11" class="mono">${esc(info.id)}</text>`)
    x += cw + 6
  }
  // Category chip: a string only (UCR-210), so a value that is no name never reaches esc().
  if (typeof info.category === 'string' && x + 40 < room) {
    const label = fit(info.category, room - x - 16, 11, 500)
    const cw = Math.round(label.length * 6 + 16)
    parts.push(`<rect x="${x + 0.5}" y="${top - 12.5}" width="${cw}" height="19" rx="9.5" fill="none" stroke="rgba(255,255,255,.22)"/>
<text x="${x + cw / 2}" y="${top + 1}" text-anchor="middle" fill="${SUB}" font-size="11" font-weight="500">${esc(label)}</text>`)
  }
  // Body
  const text = info.id === undefined ? item.text : item.text.replace(info.id, '').replace(/^\s*[:.-]?\s*/, '')
  const lines = wrap(text, w - pad * 2, 13, 400, 4)
  let y = top + 26
  const ink = item.status === 'completed' ? FAINT : LABEL
  const strike = item.status === 'completed' ? ' text-decoration="line-through"' : ''
  parts.push(`<text x="${pad}" y="${y}" fill="${ink}" font-size="13"${strike}>${lines.map((line, k) => `<tspan x="${pad}" dy="${k === 0 ? 0 : 18}">${esc(line)}</tspan>`).join('')}</text>`)
  y += (lines.length - 1) * 18 + 10
  // Agents
  if (item.owners.length > 0) {
    let ax = pad
    const widths = item.owners.map(o => Math.round(agentLabel(o).length * 7 + 14))
    // The chips leave 70 px for the working agent's text; owners past those that fit are told by one "+M" chip (UCR-160).
    const shown = ownersFit(widths, w - pad * 2 - 70, 6, more => Math.round(`+${more}`.length * 7 + 14))
    item.owners.slice(0, shown).forEach((o, k) => {
      const label = agentLabel(o)
      const cw = widths[k]!
      parts.push(`<rect x="${ax}" y="${y}" width="${cw}" height="18" rx="9" fill="${agentColor(o)}"/>
<text x="${ax + cw / 2}" y="${y + 13}" text-anchor="middle" fill="#FFFFFF" font-size="10.5" font-weight="700">${label}</text>`)
      ax += cw + 6
    })
    if (shown < item.owners.length) {
      const label = `+${item.owners.length - shown}`
      const cw = Math.round(label.length * 7 + 14)
      parts.push(`<rect x="${ax}" y="${y}" width="${cw}" height="18" rx="9" fill="rgba(255,255,255,.14)"/>
<text x="${ax + cw / 2}" y="${y + 13}" text-anchor="middle" fill="${LABEL}" font-size="10.5" font-weight="700">${label}</text>`)
      ax += cw + 6
    }
    const working = owner === ORCH ? view.orchestrator : view.agents[owner ?? 0]
    if (working !== undefined) {
      parts.push(`<text x="${ax + 2}" y="${y + 13}" fill="${SUB}" font-size="11">${esc(fit(working.description, w - ax - pad - 2, 11))}</text>`)
    }
    y += 26
  }
  if ((info.actions ?? 0) > 0) {
    y += SEND_ROW_PX
  }
  const h = y + 8
  const frame = `<rect x="0.75" y="0.75" width="${w - 1.5}" height="${h - 1.5}" rx="12" fill="${CARD}" stroke="${owner !== undefined ? agentColor(owner) : RULE}" stroke-width="${owner !== undefined ? 1.5 : 1}"/>`
  const bar = accent === undefined ? '' : `<rect x="0" y="12" width="3" height="${h - 24}" rx="1.5" fill="${accent}"/>`
  const body = item.status === 'completed' ? `<g opacity=".6">${parts.join('\n')}</g>` : parts.join('\n')
  const source = `<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(`${status.label}: ${cutText(item.text, 120)}`)}">
<style>
text{font-family:"Instrument Sans","Helvetica Neue",Arial,sans-serif;font-variant-numeric:tabular-nums;-webkit-font-smoothing:antialiased}
.mono{font-family:"Fragment Mono",ui-monospace,Menlo,monospace}
${LIGHT_CSS}
${blinks.css()}
</style>
${frame}${bar}
${body}</svg>`

  return { source, width: w, height: h, alt: `${status.label}: ${cutText(item.text, 200)}` }
}

/** The button row's height: a native button, raised one row off the card's bottom edge. */
export const SEND_ROW_PX = 60

/** The pane's card width, for laying tickets out in columns beside it. */
export function cardWidth(): number {
  return W
}

/** The pane's full width, for the board's ticket columns, which grow past the card cap (#T0040). */
export function boardWidth(): number {
  return PANE
}

/** The least width, in px, that an item's text keeps in the list view. */
const LIST_TEXT_MIN = 120
/** One owner disk's width in the list view. */
const DISK_PX = 36

/** How many owner disks a list row shows (a "+M" disk takes the place of the rest), and the px they take (UCR-160). */
function listDisks(count: number): { shown: number; used: number } {
  const shown = ownersFit(new Array<number>(count).fill(DISK_PX), INNER - 24 - LIST_TEXT_MIN, 0, () => DISK_PX)

  return { shown, used: shown < count ? shown + 1 : shown }
}

/** How many of the first `limit` items of a file run past 8 lines, for the Show full text button. */
export function longItems(file: FileView, limit: number): number {
  return file.items.slice(0, limit).filter(item => {
    const room = INNER - 24 - listDisks(item.owners.length).used * DISK_PX

    return wrap(item.text, room, 13, item.owners.length > 0 ? 500 : 400, Number.POSITIVE_INFINITY).length > MAX_LINES
  }).length
}

/** The height of an item's row in the list view, so a row that left can keep its place. */
export function listRowPx(item: ItemView, isTextOpen = false): number {
  const room = INNER - 24 - listDisks(item.owners.length).used * DISK_PX

  return 34 + (wrap(item.text, room, 13, item.owners.length > 0 ? 500 : 400, isTextOpen ? Number.POSITIVE_INFINITY : MAX_LINES).length - 1) * LINE_H
}

/** An empty space `height` px high: a transparent card with no text and no buttons, that holds a ticket's place. */
export function spaceSvg(width: number, height: number): Card {
  const w = Math.max(1, Math.round(width))
  const h = Math.max(1, Math.round(height))

  return { source: `<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}" role="presentation"></svg>`, width: w, height: h, alt: '' }
}

/**
 * One todo file as cards: the first carries its name, count and strip; then up to `limit` of its
 * items in the view's order, 40 to a card, so a file of any length stays inside the SVG limit. An
 * item longer than 8 lines stops there with an ellipsis, unless `isTextOpen` shows every item whole.
 * The owners of an item show as the disks that fit, then a "+M" disk (UCR-160).
 *
 * `gaps` holds empty space before an item of the shown list, by its index (the shown length: after
 * the last): the list view's way to keep the place of an item that left.
 */
export function fileCards(file: FileView, view: View, limit: number, isTextOpen = false, gaps: ReadonlyMap<number, number> = new Map()): Card[] {
  const shown = file.items.slice(0, limit)
  const cards: Card[] = []
  let parts: string[] = []
  let blinks = new Blinks()
  let y = 0
  let count = 0
  let first = 0
  const begin = (isFirst: boolean) => {
    parts = []
    blinks = new Blinks()
    y = 8
    count = 0
    if (isFirst) {
      y = 26
      parts.push(`<text x="${PAD}" y="${y}" fill="${LABEL}" font-size="14" font-weight="500">${esc(fit(file.name, INNER - 70, 14, 500))}</text>
<text x="${W - PAD}" y="${y}" text-anchor="end" fill="${SUB}" font-size="12">${file.done} of ${file.total}</text>`)
      parts.push(strip(PAD, y + 9, INNER, file.done, file.active, file.total))
      y += 22
    }
    y += 18
  }
  const flush = () => {
    const body = file.isArchived === true ? `<g opacity=".55">${parts.join('\n')}</g>` : parts.join('\n')
    const card = stage(y - 6, body, `${file.name}: ${file.done} of ${file.total} done${first > 0 ? `, items ${first + 1} on` : ''}`, blinks.css())
    cards.push(card)
  }
  begin(true)
  shown.forEach((item, index) => {
    y += gaps.get(index) ?? 0
    if (count === ITEMS_PER_CARD) {
      flush()
      first = index
      begin(false)
    }
    const group = file.groups?.find(one => one.from === index)
    if (group !== undefined) {
      parts.push(`<text x="${PAD}" y="${y + 2}" fill="${SUB}" font-size="12" font-weight="500">${esc(fit(group.name, INNER - 40, 12, 500))}</text>
<text x="${W - PAD}" y="${y + 2}" text-anchor="end" fill="${FAINT}" font-size="11">${group.count}</text>
<line x1="${PAD}" y1="${y + 9}" x2="${W - PAD}" y2="${y + 9}" stroke="${RULE}"/>`)
      y += 30
    }
    const isMatch = item.owners.length > 0
    const weight = isMatch ? 500 : 400
    const room = INNER - 24 - listDisks(item.owners.length).used * DISK_PX
    const lines = wrap(item.text, room, 13, weight, isTextOpen ? Number.POSITIVE_INFINITY : MAX_LINES)
    const extra = (lines.length - 1) * LINE_H
    if (isMatch) {
      parts.push(`<rect x="${PAD - 8}" y="${y - 17}" width="${INNER + 16}" height="${32 + extra}" rx="8" fill="${SUGGESTED}"/>`)
    }
    parts.push(itemMark(PAD + 6, y - 1, item.status, item.owners, view, blinks))
    const ink = isMatch || item.status === 'in_progress' ? LABEL : item.status === 'completed' ? FAINT : LABEL
    const strike = item.status === 'completed' ? ' text-decoration="line-through"' : ''
    const tspans = lines.map((line, k) => `<tspan x="${PAD + 22}" dy="${k === 0 ? 0 : LINE_H}">${esc(line)}</tspan>`).join('')
    parts.push(`<text x="${PAD + 22}" y="${y + 3}" fill="${ink}" font-size="13" font-weight="${weight}"${strike}>${tspans}</text>`)
    const disks = listDisks(item.owners.length)
    item.owners.slice(0, disks.shown).forEach((owner, k) => {
      const agent = owner === ORCH ? view.orchestrator : view.agents[owner]
      const failed = agent?.status === 'failed' || agent?.status === 'killed'
      const state = failed ? 'failed' : agent?.isEnded === false ? (isBlinking(owner, view) ? 'working' : 'steady') : 'none'
      parts.push(actor(W - PAD - 8 - k * DISK_PX, y - 1, owner, state, true, blinks))
    })
    if (disks.shown < item.owners.length) {
      parts.push(moreDisk(W - PAD - 8 - disks.shown * DISK_PX, y - 1, item.owners.length - disks.shown))
    }
    y += 34 + extra
    count += 1
  })
  y += gaps.get(shown.length) ?? 0
  if (count > 0 || cards.length === 0) {
    flush()
  }

  return cards
}

/** The height of one file row in the board header. */
const HEAD_ROW_PX = 44

/**
 * The ticket board's header: one row per file, each with its name, its own progress strip and its
 * own "done of total". With one file it is the same card as the list view's first card. A file's
 * place (its folder) shows in dim text after the name only when another row has the same name,
 * since the two rows would look the same. Archived files are grayed.
 */
export function boardHead(files: readonly FileView[]): Card {
  const counts = new Map<string, number>()
  for (const file of files) {
    counts.set(file.name, (counts.get(file.name) ?? 0) + 1)
  }
  const rows = files.map((file, i) => {
    const y = 26 + i * HEAD_ROW_PX
    const place = (counts.get(file.name) ?? 0) > 1 && file.place !== undefined && file.place !== '' ? file.place : undefined
    const room = INNER - 70
    const placeText = place === undefined ? undefined : fit(place, Math.floor(room / 2), 12)
    const nameText = fit(file.name, placeText === undefined ? room : room - placeText.length * 12 * 0.52 - 10, 14, 500)
    // The place rides in the name's own text, so the gap is the font's, not a width guess.
    const placeSpan = placeText === undefined ? '' : `<tspan dx="10" fill="${FAINT}" font-size="12" font-weight="400">${esc(placeText)}</tspan>`
    const body = `<text x="${PAD}" y="${y}" fill="${LABEL}" font-size="14" font-weight="500">${esc(nameText)}${placeSpan}</text>
<text x="${W - PAD}" y="${y}" text-anchor="end" fill="${SUB}" font-size="12">${file.isEmpty === true ? 'Empty' : `${file.done} of ${file.total}`}</text>
${strip(PAD, y + 9, INNER, file.done, file.active, file.total)}`

    return file.isArchived === true || file.isEmpty === true ? `<g opacity=".55">${body}</g>` : body
  })
  const height = 26 + Math.max(0, files.length - 1) * HEAD_ROW_PX + 34

  return stage(height, rows.join('\n'), files.map(file => (file.isEmpty === true ? `${file.name}: empty` : `${file.name}: ${file.done} of ${file.total} done`)).join('; '))
}

files.hooks/todo-markdown.ts:
/**
 * The todo Markdown grammar: item IDs, inline code, and the items of a file. The block structure
 * (checkbox lines, fences, comments, indented code) is in `markdown-blocks.ts`; it is re-exported here,
 * so every caller reads the grammar from this one module.
 */

import type { TodoItem, TodoStatus } from '../types'
import { itemKey } from './item-keys'
import { bare, CHECKBOX, exampleMask } from './markdown-blocks'

export { bare, CHECKBOX, exampleMask, expandTabs, FENCE, fenceMask, fenceOpens, fenceStep } from './markdown-blocks'
export type { Fence } from './markdown-blocks'

/**
 * An item ID without its `#`: `T` and a digit, then digits and capital letters (`T12`, `T3C`,
 * `T002A`); the mod's form of 4 or more characters in any case (`t002a`); or the older forms of other
 * letters and digits (`PROJ7`). `#TODO` is no ID, and neither is a word such as `#T1st` or `#t2a`
 * (UCR-026): a lowercase letter makes an ID only in the 4-character form.
 */
export const ID_SRC = '(?:[Tt]\\d[0-9A-Za-z]{3,}|[Tt]\\d[0-9A-Z]*|[A-Za-z]+\\d+)'
export const ITEM_ID = new RegExp(`#(${ID_SRC})\\b`)

/** An item's text as the pane shows it: Markdown bold and strike markers taken out, U+2028 and U+2029 read as spaces (UCR-201), spaces trimmed. */
export function plainText(markdown: string): string {
  return markdown.replace(/\*\*|__|~~/g, '').replace(/[\u2028\u2029]/g, ' ').trim()
}

/** The item's leading ID (no `#`): the one right after the box, at the start of its text. */
export const leadingId = (text: string): string | undefined => new RegExp(`^#(${ID_SRC})\\b`).exec(text)?.[1]

/**
 * The text with every inline code span (CommonMark: a run of backticks up to the next run of the same
 * length) blanked to spaces, so a word inside one (`` `#T002B` ``, an example) is never read as an ID
 * (UCR-146). A run with no closing run is plain text, and stays.
 *
 * Linear in the text (UCR-207): one pass finds every backtick run, indexed by its length; each opening
 * run then takes the next run of its length after it through a cursor per length that only moves
 * forward. The old scan searched to the end of the text for each unclosed run, so runs of many lengths
 * (`a``a```a`...) cost the square of the line.
 */
export function codeSpansOut(text: string): string {
  if (!text.includes('`')) {
    return text
  }
  // Every backtick run: its start and length, in order; and the run indexes of each length.
  const runs: { start: number; len: number }[] = []
  const byLen = new Map<number, number[]>()
  for (let i = 0; i < text.length; ) {
    if (text[i] !== '`') {
      i += 1
      continue
    }
    const start = i
    while (i < text.length && text[i] === '`') {
      i += 1
    }
    const len = i - start
    // Local mutation: a push, never a copy, keeps the pass linear when many runs share a length.
    const list = byLen.get(len)
    if (list === undefined) {
      byLen.set(len, [runs.length])
    } else {
      list.push(runs.length)
    }
    runs.push({ start, len })
  }
  const cursor = new Map<number, number>()
  // The first run of length `len` after run `after`, or undefined; the cursor of that length skips the runs passed.
  const nextOf = (len: number, after: number): number | undefined => {
    const list = byLen.get(len)!
    let at = cursor.get(len) ?? 0
    while (at < list.length && list[at]! <= after) {
      at += 1
    }
    cursor.set(len, at)

    return list[at]
  }
  let out = ''
  let copied = 0
  for (let r = 0; r < runs.length; ) {
    const run = runs[r]!
    const close = nextOf(run.len, r)
    if (close === undefined) {
      r += 1
      continue
    }
    const end = runs[close]!.start + run.len
    out += text.slice(copied, run.start) + ' '.repeat(end - run.start)
    copied = end
    r = close + 1
  }

  return out + text.slice(copied)
}

/** A `T` ID anywhere in a text (no `#`), outside inline code: the only form that counts as an item's own ID when it is not the leading one. */
const trailingTicketId = (text: string): string | undefined => /#([Tt]\d[0-9A-Za-z]{3,}|[Tt]\d[0-9A-Z]*)\b/.exec(codeSpansOut(text))?.[1]

/**
 * The item's own ID for a checkbox line's text. A leading ID is its own. Else the first `T` ID anywhere,
 * unless another ticket owns that ID as its leading ID (`owned`, lowercase): then the line only
 * refers to that ticket and has no ID of its own. Words that look like IDs (`#h264`, `#utf8`) are
 * never an ID unless they lead the line (UCR-026).
 */
function ownId(text: string, owned: ReadonlySet<string>): string | undefined {
  const lead = leadingId(text)
  if (lead !== undefined) {
    return lead
  }
  const first = trailingTicketId(text)

  return first !== undefined && owned.has(first.toLowerCase()) ? undefined : first
}

/**
 * Per line of a file (`undefined` for a line that is no item, or sits in a code fence or an HTML
 * comment): the line's own ID. A leading ID is its own, unless an earlier line of the file leads
 * with the same ID; a `T` ID elsewhere is its own only when no ticket of the file
 * (or of `extra`, lowercase) leads with it and no earlier line already took it. So a reference line
 * above its ticket has no ID, and two lines that name one ID do not share a key (UCR-025, UCR-026).
 */
export function lineOwnIds(lines: readonly string[], extra: ReadonlySet<string> = new Set()): (string | undefined)[] {
  const isFenced = exampleMask(lines)
  const texts = lines.map((line, at) => {
    const match = isFenced[at] === true ? null : CHECKBOX.exec(line)

    return match === null ? undefined : plainText(match[2] ?? '')
  })
  const owned = new Set(extra)
  for (const text of texts) {
    const lead = text === undefined ? undefined : leadingId(text)
    if (lead !== undefined) {
      owned.add(lead.toLowerCase())
    }
  }
  const claimed = new Set<string>()
  const led = new Set<string>()

  return texts.map(text => {
    if (text === undefined) {
      return undefined
    }
    const id = ownId(text, owned)
    const lead = leadingId(text)
    if (lead !== undefined) {
      // A later line that leads with the same ID has no ID of its own: one key never names two lines, so a
      // button on the second never writes the first, and numbering gives the second an ID (UCR-025, UCR-026).
      if (led.has(lead.toLowerCase())) {
        return undefined
      }
      led.add(lead.toLowerCase())
    } else if (id !== undefined) {
      if (claimed.has(id.toLowerCase())) {
        return undefined
      }
      claimed.add(id.toLowerCase())
    }

    return id
  })
}

/** The checkbox items of a todo file's lines, each with the index of its line. Code fences and HTML comments hold none. */
export function itemsAt(rawLines: readonly string[]): { at: number; item: TodoItem }[] {
  const lines = rawLines.map(bare)
  const isFenced = exampleMask(lines)
  const ids = lineOwnIds(lines)
  const found: { at: number; item: TodoItem }[] = []
  const seen = new Map<string, number>()
  for (const [at, line] of lines.entries()) {
    const match = isFenced[at] === true ? null : CHECKBOX.exec(line)
    if (match === null) {
      continue
    }
    const box = match[1] ?? ' '
    const status: TodoStatus =
      box === 'x' || box === 'X' ? 'completed' : box === '~' ? 'in_progress' : box === '>' ? 'queued' : 'pending'
    const text = plainText(match[2] ?? '')
    const id = ids[at]
    const item: TodoItem = id === undefined ? { text, status } : { text, status, id }
    // A line whose key an earlier line of the file has gets its place among them (UCR-025): every key names one line.
    const key = itemKey(item)
    const nth = (seen.get(key) ?? 0) + 1
    seen.set(key, nth)
    found.push({ at, item: nth === 1 ? item : { ...item, nth } })
  }

  return found
}

/** Reads the checkbox items of one todo file, in the format the RULES block gives Claude. */
export function parseTodo(markdown: string): TodoItem[] {
  return itemsAt(markdown.split('\n')).map(one => one.item)
}

export function count(items: readonly TodoItem[]): { done: number; active: number; total: number } {
  return {
    done: items.filter(item => item.status === 'completed').length,
    active: items.filter(item => item.status === 'in_progress').length,
    total: items.length,
  }
}

files.hooks/todo-read.ts:
/** The result of one todo file read: its text, no file there, or a read that failed and why. */

/**
 * What a read of a todo file gave (UCR 5c). `missing`: nothing stands at the path. `failed`: the file
 * is there (or that cannot be told) and did not read; it is never an empty file, and never absent.
 * `error` is what the engine threw, when it threw.
 */
export type TodoRead = { kind: 'ok'; text: string } | { kind: 'missing'; error?: unknown } | { kind: 'failed'; reason: string; error?: unknown }

/** The words of a failure: the error's message, else its text. */
export function reasonOf(error: unknown): string {
  return error instanceof Error ? error.message : String(error)
}

/** The words of a read that gave no text. */
export const readReason = (read: Exclude<TodoRead, { kind: 'ok' }>): string => (read.kind === 'missing' ? 'no such file' : read.reason)

/** A todo file that did not read, named: the error that stops a caller that needs every file (UCR-108). */
export class TodoReadError extends Error {
  readonly path: string
  readonly reason: string

  constructor(path: string, reason: string) {
    super(`${path} did not read: ${reason}`)
    this.path = path
    this.reason = reason
  }
}

files.hooks/token-usage.ts:
/** Token usage: the tokens of one turn, and the stored session total read back. */

import type { Usage } from './card-types'

/** Reads a stored count back: finite, non-negative numbers only, the count at compact no more than the total; undefined when it is not one. */
export function readKeptUsage(stored: unknown): Usage | undefined {
  const raw = stored as Partial<Record<keyof Usage, unknown>> | null | undefined
  if (typeof raw !== 'object' || raw === null) {
    return undefined
  }
  const { tokens, since, atCompact, compactAt } = raw
  if (typeof tokens !== 'number' || !Number.isFinite(tokens) || tokens < 0 || typeof since !== 'number' || !Number.isFinite(since)) {
    return undefined
  }

  return {
    tokens,
    since,
    // The count at the last compaction is part of the total: clamped to it (UCR-216), so "since compact" is never negative.
    ...(typeof atCompact === 'number' && Number.isFinite(atCompact) && atCompact >= 0 ? { atCompact: Math.min(atCompact, tokens) } : {}),
    ...(typeof compactAt === 'number' && Number.isFinite(compactAt) ? { compactAt } : {}),
  }
}

/** The tokens one model request (or turn) used, every kind summed. */
export function turnTokens(used: { input_tokens: number; output_tokens: number; cache_read_input_tokens: number; cache_creation_input_tokens: number }): number {
  // A field the engine leaves out (or sets to null or a non-number) counts 0, so the sum is never NaN (UCR-155).
  const part = (n: unknown) => (typeof n === 'number' && Number.isFinite(n) && n > 0 ? n : 0)

  return part(used.input_tokens) + part(used.output_tokens) + part(used.cache_read_input_tokens) + part(used.cache_creation_input_tokens)
}

/** One model request's usage as the engine reports it, in a step's result or its stop chunk. */
export type StepUsage = Parameters<typeof turnTokens>[0]

/**
 * The usage one model request is counted by: the step result's, unless it is missing (or null) or counts no
 * token, then the stop chunk's (UCR-110: a result of all zeros hid a stop chunk with usage). The
 * two are one report of one request, so the count never adds both.
 */
export function stepUsage(result: StepUsage | null | undefined, stop: StepUsage | undefined): StepUsage | undefined {
  return result != null && turnTokens(result) > 0 ? result : (stop ?? result ?? undefined)
}

files.hooks/unread-files.ts:
/**
 * The streak of a todo file that keeps failing to read when new IDs are chosen (UCR-108): how many
 * passes in a row it failed (for any reason), and when it is skipped.
 */

/** Passes in a row a file must fail, for any reason, before new IDs are chosen without it. */
export const SKIP_AFTER = 3

/** One file's streak: the reason of its last failure, in how many passes in a row it failed, and the last of those passes. */
export type UnreadStreak = { reason: string; count: number; pass: number }

/**
 * The streak after a failure in pass `pass`: one more for a new pass, as it was for a second failure
 * in the same pass. The failures count by file, not by reason (UCR-108): a file whose reason changes
 * from pass to pass (`EIO`, then `ETIMEDOUT`) fails as surely as one that fails the same way, so the
 * streak goes on, with the newest reason. Only a good read ends it (the caller deletes it).
 */
export function nextStreak(was: UnreadStreak | undefined, reason: string, pass: number): UnreadStreak {
  if (was === undefined) {
    return { reason, count: 1, pass }
  }

  return was.pass === pass ? { ...was, reason } : { reason, count: was.count + 1, pass }
}

/** True when the file is skipped: it failed SKIP_AFTER passes in a row. */
export const isSkipped = (streak: UnreadStreak): boolean => streak.count >= SKIP_AFTER

files.hooks/unread-folders.ts:
/** The scan folders that hold a place the last scan could not read. */

import type { ClaimFolder } from './claim-keeping'

/**
 * The paths of the folders in `folders` that hold one of the `unread` places (UCR-127). A place is
 * named as the scan names it: the folder (`<label>`), its archive (`<label>/archive`) or a file
 * (`<label>/<name>`), where the label is the folder's `rel`, else its path. A place goes to the
 * folder with the longest label it falls under, so a folder nested in another's path takes only
 * its own places. A place under no folder marks every folder: it is not known which one holds it,
 * and keeping too much is safe where dropping is not.
 */
export function foldersWithUnread(unread: readonly string[], folders: readonly ClaimFolder[]): Set<string> {
  const out = new Set<string>()
  for (const place of unread) {
    let best: ClaimFolder | undefined
    for (const folder of folders) {
      const label = folder.rel ?? folder.folder
      if ((place === label || place.startsWith(`${label}/`)) && (best === undefined || label.length > (best.rel ?? best.folder).length)) {
        best = folder
      }
    }
    if (best === undefined) {
      return new Set(folders.map(folder => folder.folder))
    }
    out.add(best.folder)
  }

  return out
}

files.hooks/tool-calls.ts:
/** What a tool call shows on the pane: its few words, its summary line and its detail line. */

import { cutText, cutUnits } from './card-text'
import { relIn } from './path-forms'
import { hasSecret, HIDDEN, hideSecrets } from './secrets'

/** A few words on what a tool call does, from its arguments. */
export function describeCall(tool: string, input: Record<string, unknown>): string {
  for (const key of ['description', 'command', 'file_path', 'pattern', 'query', 'url', 'path', 'prompt']) {
    const value = input[key]
    if (typeof value === 'string' && value.length > 0) {
      // A command, URL or pattern with a secret in any line shows as "(hidden)", as callDetail hides it.
      const line = hasSecret(value) ? '(hidden)' : (value.split('\n')[0] ?? '')

      return `${tool}: ${line.length > 60 ? `${cutText(line, 57)}...` : line}`
    }
  }

  return tool
}

/** A tool call's own one-line summary: its `description` as written, else a few words from its arguments. */
export function callSummary(tool: string, input: Record<string, unknown>): string {
  const description = input.description

  return typeof description === 'string' && description.trim() !== '' ? (hasSecret(description) ? `${tool}: (hidden)` : description.trim().split('\n')[0]!) : describeCall(tool, input)
}
/** The longest detail kept per history entry; the card cuts it again to fit its line. */
export const DETAIL_MAX = 300

/**
 * The native detail of a tool call, from its input: the command, path, pattern or URL it ran with.
 * Undefined when the tool has none (MCP tools), or the detail only repeats the summary `line`. A
 * path inside `root` shows relative to it. A detail of any tool that looks like it holds a secret shows
 * as "(hidden)".
 */
export function callDetail(tool: string, input: Record<string, unknown>, line: string, root?: string): string | undefined {
  const text = (key: string): string | undefined => {
    const value = input[key]

    return typeof value === 'string' && value.trim() !== '' ? value.trim() : undefined
  }
  const rel = (path: string | undefined): string | undefined => (path === undefined ? undefined : (relIn(path, root) ?? path))
  let detail: string | undefined
  if (tool === 'Bash') {
    const command = text('command')
    detail = command === undefined ? undefined : hideSecrets(command) === '(hidden)' ? '(hidden)' : command.split('\n')[0]!.trim()
  } else if (tool === 'Read' || tool === 'Edit' || tool === 'Write') {
    detail = rel(text('file_path'))
  } else if (tool === 'NotebookEdit') {
    detail = rel(text('file_path') ?? text('notebook_path'))
  } else if (tool === 'Grep') {
    const pattern = text('pattern')
    const path = rel(text('path'))
    detail = pattern === undefined ? undefined : path === undefined ? pattern : `${pattern}  ${path}`
  } else if (tool === 'Glob') {
    detail = text('pattern')
  } else if (tool === 'WebFetch') {
    detail = text('url')
  } else if (tool === 'WebSearch') {
    detail = text('query')
  } else if (tool === 'Agent' || tool === 'Task') {
    detail = [text('subagent_type'), text('model')].filter(part => part !== undefined).join(', ')
  } else if (tool === 'Skill') {
    detail = text('skill')
  }
  // Every detail type is checked, on the whole input text and again on the one line that shows.
  detail = detail === undefined ? undefined : cutUnits(hideSecrets(detail), DETAIL_MAX)

  return detail === undefined || detail === '' || detail === line ? undefined : detail
}

/**
 * An agent's current-call line as kept, with a secret hidden: `Bash: (hidden)` when the line names
 * its tool, else "(hidden)". For a line stored by an older version, which no check saw (UCR-029).
 */
export function hideDoing(doing: string): string {
  if (!hasSecret(doing)) {
    return doing
  }
  const tool = /^([\w.-]{1,80}): /.exec(doing)?.[1]

  return tool === undefined ? HIDDEN : `${tool}: ${HIDDEN}`
}

files.hooks/view-model.ts:
/** The view the pane draws: files, items, agents and the orchestrator, worked out from the todo and the rows. */

import type { AgentRow, TodoFile } from '../types'
import { isEnded } from './agent-ends'
import { colorSlots } from './agent-colors'
import { AGENT_COLORS, ORCH, setColorSlots } from './agent-identity'
import type { AgentView, FileView, ItemStatus, ItemView, View } from './card-types'
import { categoryOf } from './categories'
import type { CategoryBook } from './categories'
import { fileId, filePath, itemKey, keptKey, qualifiedKey, storedKey } from './item-keys'
import { linkAgents } from './links'
import { folderPlace } from './repo-folders'
import { ticketValue } from './ticket-ids'
import { count } from './todo-markdown'

/**
 * Every open or in-progress item of the live files whose text holds every word of the query. Done
 * and archived items are not searched: the board shows no done tickets, and Show completed opens them.
 */
export function searchTodo(files: readonly FileView[], query: string): FileView[] {
  const words = query.toLowerCase().split(/\s+/).filter(word => word !== '')
  if (words.length === 0) {
    return []
  }

  return files
    .filter(file => file.isArchived !== true)
    .map(file => ({ ...file, items: file.items.filter(item => item.status !== 'completed' && words.every(word => item.text.toLowerCase().includes(word))) }))
    .filter(file => file.items.length > 0)
}

/** The orchestrator as the view needs it: its ticket keys, whether a turn runs, and its call summary. */
export type OrchestratorState = { keys: ReadonlySet<string>; isRunning: boolean; doing?: string; toolCalls: number; title?: string }

/** The orchestrator card's title: Claude's headline, else the first ticket it owns, and how many more. */
export function orchestratorTitle(title: string | undefined, tickets: readonly string[]): string {
  const first = tickets[0]
  if (title !== undefined && title !== '') {
    return title
  }

  return first === undefined ? 'Orchestrator' : tickets.length > 1 ? `${first} and ${tickets.length - 1} more` : first
}

/** What the pane draws, worked out once for the cards and the terminal alike. */
export function buildView(list: readonly TodoFile[], rows: readonly AgentRow[], now: number, orch?: OrchestratorState): View {
  const links = linkAgents(list, rows)
  // Every card drawn from this view takes its agent colors from these slots.
  setColorSlots(colorSlots(rows.map(row => ({ startedAt: row.startedAt, endedAt: row.endedAt, idleSince: row.idleSince, isEnded: isEnded(row.status) })), AGENT_COLORS.length))
  const itemOwners = new Map<string, number[]>()
  const fileOwners = new Map<string, number[]>()
  rows.forEach((row, i) => {
    for (const link of links.get(row.id) ?? []) {
      const key = `${link.file}:${link.index}`
      itemOwners.set(key, [...(itemOwners.get(key) ?? []), i])
      fileOwners.set(link.file, [...new Set([...(fileOwners.get(link.file) ?? []), i])])
    }
  })
  // The orchestrator owns a ticket only while no live agent works it, then last in the item's list.
  const orchLinks: string[] = []
  const isLive = (i: number) => !isEnded(rows[i]!.status) && rows[i]!.idleSince === undefined
  if (orch !== undefined && orch.keys.size > 0) {
    for (const file of list.filter(one => one.isArchived !== true)) {
      file.items.forEach((item, index) => {
        if (item.status !== 'completed' && orch.keys.has(keptKey(file, item))) {
          const key = `${fileId(file)}:${index}`
          // A ticket handed off to a live agent is that agent's alone (#T0044): its card and its owner disk.
          if ((itemOwners.get(key) ?? []).some(isLive)) {
            return
          }
          itemOwners.set(key, [...(itemOwners.get(key) ?? []), ORCH])
          fileOwners.set(fileId(file), [...new Set([...(fileOwners.get(fileId(file)) ?? []), ORCH])])
          orchLinks.push(item.text)
        }
      })
    }
  }

  // One FileView per file: the ticket board shares its columns across files, and the header card
  // has one row per file. Each item keeps its source (folder, file, path) for the writes and the
  // prompts. Sources run primary folder first, then by folder path, so the order is stable.
  const sources = [...list].sort((a, b) => Number(a.isOther === true) - Number(b.isOther === true) || ((a.rel ?? a.folder) < (b.rel ?? b.folder) ? -1 : (a.rel ?? a.folder) > (b.rel ?? b.folder) ? 1 : 0))
  // The pane ID is the name, kept short for the common case; a repeated name takes its folder too.
  const nameCount = new Map<string, number>()
  for (const file of sources) {
    nameCount.set(file.name, (nameCount.get(file.name) ?? 0) + 1)
  }
  // A file's counts include the done tickets of its archive file, so archiving leaves its bar as it was.
  const archiveDone = (file: TodoFile) => count(list.find(one => one.isArchived === true && one.folder === file.folder && one.name === `archive/${file.name}`)?.items ?? []).done
  const files: FileView[] = sources.map(file => {
    const own = count(file.items)
    const inArchive = file.isArchived === true ? 0 : archiveDone(file)
    const indexed = file.items.map((item, index) => ({ file, item, owners: itemOwners.get(`${fileId(file)}:${index}`) ?? [] }))
    // An open or queued ticket that an agent holds shows in In progress (ticketColumns), so it counts there.
    const held = indexed.filter(one => (one.item.status === 'pending' || one.item.status === 'queued') && one.owners.length > 0).length
    const [done, active, total] = [own.done + inArchive, own.active + held, own.total + inArchive]
    const linked = indexed.filter(one => one.owners.length > 0)
    const rest = [
      ...indexed.filter(one => one.item.status === 'in_progress'),
      ...indexed.filter(one => one.item.status === 'queued'),
      ...indexed.filter(one => one.item.status === 'pending'),
      ...indexed.filter(one => one.item.status === 'completed'),
    ].filter(one => one.owners.length === 0)
    const shown = [...linked, ...rest]

    return {
      name: file.name,
      id: (nameCount.get(file.name) ?? 0) > 1 ? fileId(file) : file.name,
      place: folderPlace(file.rel ?? file.folder),
      done,
      active,
      total,
      owners: fileOwners.get(fileId(file)) ?? [],
      items: shown.map(one => ({
        text: one.item.text,
        status: one.item.status,
        owners: one.owners,
        key: qualifiedKey(one.file, one.item),
        localKey: itemKey(one.item),
        folder: one.file.folder,
        file: one.file.name,
        path: filePath(one.file),
      })),
      mtimeMs: file.mtimeMs,
      ...(file.isArchived === true ? { isArchived: true } : {}),
    }
  })
  files.sort((a, b) => {
    const linkA = a.owners.length > 0 ? 0 : 1
    const linkB = b.owners.length > 0 ? 0 : 1
    const openA = a.done < a.total ? 0 : 1
    const openB = b.done < b.total ? 0 : 1

    // The repo root's own files first, then the rest.
    const rootA = (a.place ?? '') === '' ? 0 : 1
    const rootB = (b.place ?? '') === '' ? 0 : 1

    return rootA - rootB || linkA - linkB || openA - openB || b.mtimeMs - a.mtimeMs
  })

  const current = files.filter(file => file.isArchived !== true)
  const archivedFiles = files.filter(file => file.isArchived === true)
  const archived = count(list.filter(file => file.isArchived === true).flatMap(file => file.items)).done
  // The heading counts what the board shows: the live files with the done tickets of their own archive
  // files (the same counts as each file's bar), not an archive file that has no live file; and an open
  // ticket an agent works on counts as in progress, as the In progress column shows it.
  const all = { done: current.reduce((sum, file) => sum + file.done, 0), active: current.reduce((sum, file) => sum + file.active, 0), total: current.reduce((sum, file) => sum + file.total, 0) }

  return {
    files: [...current.filter(file => file.done < file.total), ...current.filter(file => file.done === file.total), ...archivedFiles],
    archived,
    agents: rows.map((row, i) => ({
      index: i,
      id: row.id,
      description: row.description,
      type: row.type,
      model: row.model,
      status: row.status,
      isEnded: isEnded(row.status),
      isIdle: !isEnded(row.status) && row.idleSince !== undefined,
      idleSince: row.idleSince,
      startedAt: row.startedAt,
      endedAt: row.endedAt,
      toolCalls: row.toolCalls,
      tokens: row.tokens,
      doing: row.doing,
      links: (links.get(row.id) ?? []).map(link => link.item.text),
      progress: row.progress,
    })),
    ...all,
    live: rows.filter(row => !isEnded(row.status) && row.idleSince === undefined).length,
    now,
    // The orchestrator card shows only while the main conversation works a ticket itself (#T0044).
    ...(orch === undefined || orchLinks.length === 0 || !orch.isRunning
      ? {}
      : {
          orchestrator: {
            index: ORCH,
            description: orchestratorTitle(orch.title, orchLinks),
            type: 'main conversation',
            status: orch.isRunning ? 'running' : 'idle',
            isEnded: false,
            isIdle: !orch.isRunning,
            startedAt: now,
            toolCalls: orch.toolCalls,
            ...(orch.doing === undefined ? {} : { doing: orch.doing }),
            links: orchLinks,
          } satisfies AgentView,
        }),
  }
}

/**
 * The agents in three groups: live, idle (finished but never stopped, always shown, since an open
 * task is worth a look), and finished, most recently ended first, so the bottom of the list is the
 * ledger of who ran. `shown` is what the pane lists: the finished ones only with `showFinished`.
 */
export function ledger(view: View, showFinished: boolean): { active: AgentView[]; idle: AgentView[]; finished: AgentView[]; shown: AgentView[] } {
  const active = view.agents.filter(agent => !agent.isEnded && !agent.isIdle)
  const idle = view.agents.filter(agent => !agent.isEnded && agent.isIdle)
  const finished = view.agents.filter(agent => agent.isEnded).sort((a, b) => (b.endedAt ?? 0) - (a.endedAt ?? 0))

  return { active, idle, finished, shown: showFinished ? [...active, ...idle, ...finished] : [...active, ...idle] }
}

/**
 * The todo files as the pane lists them: each file with open items, its open items only. With
 * `showCompleted`, every item shows, done ones last, then the complete files, then the archive.
 */
export function todoLedger(view: View, showCompleted = false): FileView[] {
  if (showCompleted) {
    return view.files
  }

  return view.files
    .filter(file => file.isArchived !== true && file.done < file.total)
    .map(file => ({ ...file, items: file.items.filter(item => item.status !== 'completed') }))
}

/**
 * What the todo area draws. The list view draws one card set per file. The ticket view draws one
 * board: a single FileView holding every file's items, files in their order (the tiebreak within
 * a column), with `rows` the files for the board's header. No files, no board.
 */
export function boardTargets(entries: readonly { file: FileView; prefix: string }[], isTickets: boolean): { file: FileView; prefix: string; rows: FileView[] }[] {
  if (!isTickets) {
    return entries.map(one => ({ ...one, rows: [one.file] }))
  }
  const first = entries[0]
  if (first === undefined) {
    return []
  }
  const files = entries.map(one => one.file)
  const file: FileView = {
    name: 'board',
    id: 'board',
    done: files.reduce((sum, one) => sum + one.done, 0),
    active: files.reduce((sum, one) => sum + one.active, 0),
    total: files.reduce((sum, one) => sum + one.total, 0),
    owners: [...new Set(files.flatMap(one => one.owners))],
    items: files.flatMap(one => one.items.map(item => (item.file === undefined ? { ...item, file: one.name } : item))),
    mtimeMs: Math.max(0, ...files.map(one => one.mtimeMs)),
  }

  return [{ file, prefix: first.prefix, rows: files }]
}

export type TicketColumn = { name: string; items: ItemView[] }

/** How the board orders the tickets of a column: `group` (agent, category, file order) or `recency` (newest ID first). */
export type TicketOrder = 'group' | 'recency'

/**
 * The value of an item's ticket ID on the number line (`ticketValue`), which grows with each new ID;
 * undefined for an item with no `#T` ID.
 */
export function itemIdValue(item: ItemView): number | undefined {
  const key = item.localKey ?? item.key

  return key.startsWith('#') ? ticketValue(key.slice(1)) : undefined
}

/**
 * A file's tickets as board columns: In progress, Queued (`- [>]`, the work slated next) and Open;
 * done tickets have no column (Show completed opens them). An open or queued ticket that a live
 * agent works on goes in In progress, and shows as in progress, though its box is still `- [ ]` or
 * `- [>]`. Within a column, the tickets an agent works on come first, then by category in the
 * order the categories were made, then in file order. With `order` set to `recency` (#T004F), each
 * column is newest first by ticket ID value instead; a ticket with no ID comes last, in file order.
 */
export function ticketColumns(given: readonly ItemView[], current: CategoryBook, order: TicketOrder = 'group'): TicketColumn[] {
  const items = given.map(item => ((item.status === 'pending' || item.status === 'queued') && item.owners.length > 0 ? { ...item, status: 'in_progress' as const, heldFrom: item.status } : item))
  const rank = (item: ItemView) => {
    const category = categoryOf(current, storedKey(item.key))
    const at = category === undefined ? current.categories.length : current.categories.indexOf(category)

    return (item.owners.length > 0 ? 0 : 1) * 100 + (at < 0 ? current.categories.length : at)
  }
  const newer = (a: ItemView, b: ItemView) => (itemIdValue(b) ?? -1) - (itemIdValue(a) ?? -1)
  const column = (name: string, status: ItemStatus) => ({
    name,
    items: items
      .map((item, index) => ({ item, index }))
      .filter(({ item }) => item.status === status)
      .sort((a, b) => (order === 'recency' ? newer(a.item, b.item) : rank(a.item) - rank(b.item)) || a.index - b.index)
      .map(({ item }) => item),
  })

  return [column('In progress', 'in_progress'), column('Queued', 'queued'), column('Open', 'pending')]
}

/**
 * How many board columns sit side by side in `width` px: the most, up to `columns`, that each keep
 * `min` px for a ticket with `gap` px between them; 1 when none does. The columns past that count
 * wrap to the next row.
 */
export function columnsThatFit(width: number, columns: number, gap: number, min: number): number {
  for (let n = Math.max(1, columns); n > 1; n -= 1) {
    if (Math.floor((width - (n - 1) * gap) / n) >= min) {
      return n
    }
  }

  return 1
}

/**
 * A board column's share of the pane, by the number of columns in its row; a ticket is drawn this
 * wide. A last row with fewer columns widens them to fill it (#T0042): Open goes double wide under the other two.
 */
export function columnShare(inRow: number): number {
  return inRow >= 3 ? 0.32 : inRow === 2 ? 0.49 : 1
}

/** The board's columns in rows of `perRow`, left to right: the rows the board draws one under another (#T0041). */
export function rowsOf<T>(columns: readonly T[], perRow: number): T[][] {
  const n = Math.max(1, Math.floor(perRow))
  const rows: T[][] = []
  for (let i = 0; i < columns.length; i += n) {
    rows.push(columns.slice(i, i + n))
  }

  return rows
}

files.hooks/time-limit.ts:
/** The time limit of an outside call or a job: how long the mod waits before it takes it as failed. */

/**
 * How long the mod waits for one outside call (a trash command, osascript, rmdir, mkdir, git, printenv,
 * open) or one job under the writer lock before it takes it as failed (UCR-176, UCR-230).
 */
export const RUN_LIMIT_MS = 20_000

/** The result of a call that ran out of time. */
export const TIMED_OUT = Symbol('timed out')

/**
 * The value of `work`, or `TIMED_OUT` when it has not settled after `ms` (UCR-176). `after` is the
 * engine's timer (`$.clock.after`), so a test clock drives it. A call that never returns then no
 * longer holds the writer lock: the job goes on and the lock is freed. The call itself is not
 * stopped (the engine gives no way to); its late result is dropped.
 */
export function inTime<T>(work: Promise<T>, ms: number, after: (ms: number, fire: () => void) => unknown): Promise<T | typeof TIMED_OUT> {
  return new Promise((resolve, reject) => {
    let isDone = false
    const settle = (finish: () => void) => {
      if (!isDone) {
        isDone = true
        finish()
      }
    }
    // The work is watched before the timer is set, and a refused timer is caught, so neither leaves a
    // rejection unhandled (the same order as failAfter; an unhandled one ends the test process).
    work.then(
      value => settle(() => resolve(value)),
      (error: unknown) => settle(() => reject(error)),
    )
    try {
      const timer = after(ms, () => settle(() => resolve(TIMED_OUT)))
      if (typeof (timer as { then?: unknown } | null)?.then === 'function') {
        void (timer as Promise<unknown>).then(undefined, () => undefined)
      }
    } catch {
      // A timer that cannot be set leaves the call unbounded; the work still settles the result.
    }
  })
}

/**
 * How long one store call (`$.store.get` or `$.store.set`) may take before it counts as failed
 * (UCR-219). A store call is local and takes milliseconds; the limit is for one that never returns,
 * which would otherwise hold every hook that waits on the load, for the whole session.
 */
export const STORE_LIMIT_MS = 5000

/** The failure of a call that gave no answer within its time limit (failAfter). */
export class NoAnswer extends Error {}

/**
 * The value of `work`, or a rejection when it has not settled after `ms` (UCR-219): a store call
 * that never returns is a failed call, which every caller already handles (a failed read is not an
 * absent key, a failed write is tried again). The call itself is not stopped; a late result is
 * dropped. The work is watched before the timer is set, so a timer that cannot be set (the engine
 * refuses it as the session ends) rejects this call and never leaves the work's own failure
 * unhandled.
 */
export function failAfter<T>(work: Promise<T>, ms: number, after: (ms: number, fire: () => void) => unknown): Promise<T> {
  return new Promise((resolve, reject) => {
    let isDone = false
    const settle = (finish: () => void) => {
      if (!isDone) {
        isDone = true
        finish()
      }
    }
    work.then(
      value => settle(() => resolve(value)),
      (error: unknown) => settle(() => reject(error)),
    )
    try {
      const timer = after(ms, () => settle(() => reject(new NoAnswer(`no answer within ${ms / 1000} s`))))
      // An engine call answers with a promise: a refused timer rejects it, and that is this call's failure.
      if (typeof (timer as { then?: unknown } | null)?.then === 'function') {
        void (timer as Promise<unknown>).then(undefined, (error: unknown) => settle(() => reject(error)))
      }
    } catch (error) {
      settle(() => reject(error))
    }
  })
}

files.hooks/write-lock.ts:
/** The write lock: todo file writes of this session run one after another. */

/**
 * The one writer lock of the todo files: a promise chain, so a user action waits its turn, and a
 * count of the jobs queued or running, so a scan writer sees the lock held at once (no gap between
 * two chained jobs). Two writers never overlap, which keeps one from writing over the other's change.
 */
let writeChain: Promise<unknown> = Promise.resolve()
let writeJobs = 0

/** Runs `job` once every earlier writer is done. A failed job does not break the chain. */
export function withWriteLock<T>(job: () => Promise<T>): Promise<T> {
  writeJobs += 1
  const run = writeChain.then(job)
  writeChain = run.then(() => undefined, () => undefined).finally(() => {
    writeJobs -= 1
  })

  return run
}

/** For a scan writer: runs `job` if no writer holds the lock, else skips this scan (undefined). */
export async function tryWriteLock<T>(job: () => Promise<T>): Promise<T | undefined> {
  return writeJobs > 0 ? undefined : withWriteLock(job)
}

files.hooks/deferred-tickets.ts:
/** The ticket IDs that Claude's own text puts off until later: "after X lands, #T0042 is next". */

import { ID_SRC } from './todo-markdown'

/** The words that put work off: the ticket is next, or waits for an event. */
const DEFER = /\b(?:after|afterwards?|next|once|later|queue|queued|follow[- ]?up|until|when\s+\S+\s+(?:lands|is\s+done|finishes))\b/i

/** One sentence: up to a full stop, question or exclamation mark followed by a space, or a line break. */
const SENTENCES = /[^.!?\n]+(?:[.!?](?=\s|$))?/g

/**
 * The IDs (`T0042`, uppercase, no `#`) named in a sentence of `text` that also holds a word that puts
 * work off. Each ID once, in the order of the text. A match is a hint, never a fact: the mod only asks
 * Claude to queue the ticket, it never moves it on a match.
 */
export function deferredIds(text: string): string[] {
  const found = new Set<string>()
  for (const sentence of text.match(SENTENCES) ?? []) {
    if (!DEFER.test(sentence)) {
      continue
    }
    for (const match of sentence.matchAll(new RegExp(`#(${ID_SRC})\\b`, 'g'))) {
      found.add((match[1] ?? '').toUpperCase())
    }
  }

  return [...found]
}

files.hooks/stop-queue.ts:
/** The tickets an edit took out of progress back to open: the ones the mod moves to queued. */

import type { ItemStatus } from './card-types'

/**
 * The keys whose ticket was in progress before an edit and open after it. Claude stopped work on
 * them but did not finish them, so they are next work: the mod writes `- [>]` for them. A ticket
 * already queued or open before the edit is not in the list, so an edit that sets a queued ticket
 * to open keeps it open: that is how Claude drops work it will not do next.
 */
export function stoppedKeys(before: ReadonlyMap<string, ItemStatus>, after: ReadonlyMap<string, ItemStatus>): string[] {
  return [...after].filter(([key, status]) => status === 'pending' && before.get(key) === 'in_progress').map(([key]) => key)
}

files.hooks/agent-room.ts:
// The room the pane holds for the agent area (#T004L): empty cards that keep its height steady while three agent cards or fewer show.

import { AGENT_CARD_MIN_PX, timelineHeight } from './agent-cards'
import type { Card } from './card-types'
import { stage } from './card-stage'

/**
 * The agent cards the held room covers. The desktop pane scrolls by pixels and tells the mod
 * nothing of it, so an agent area that grows or shrinks moves the board below it under the reader.
 * Up to this many cards the area keeps its height; past it, each card more moves the board.
 */
export const HELD_AGENTS = 3

/** The slots of the agent area at the held size: the timeline, the orchestrator card and three agent cards. */
export const HELD_SLOTS = HELD_AGENTS + 2

/** The least height the held area takes: a timeline of three strips, and four of the smallest agent cards (the orchestrator's and three). */
export const HELD_FLOOR_PX = timelineHeight(HELD_AGENTS) + (HELD_AGENTS + 1) * AGENT_CARD_MIN_PX

/** The tallest the agent area was drawn this session at the held size or less, in px. */
export type AgentRoom = { tallestPx: number }

export const NO_ROOM: AgentRoom = { tallestPx: 0 }

/**
 * The blank slots that hold the agent area at its height, for the drawn cards' heights in px and
 * the count of agent cards among them. One blank for each slot the cards leave empty, so the count
 * of slots (and of the row gaps between them) stays the same; their heights fill what the cards
 * leave short of the tallest the area was. Past HELD_AGENTS agent cards nothing is held, and the
 * room is not grown, so the area goes back to its held height once the extra cards leave.
 */
export function holdRoom(room: AgentRoom, cardPx: readonly number[], agentCards: number): { room: AgentRoom; blanks: number[] } {
  if (agentCards > HELD_AGENTS) {
    return { room, blanks: [] }
  }
  const drawn = cardPx.reduce((sum, px) => sum + px, 0)
  const tallestPx = Math.max(room.tallestPx, HELD_FLOOR_PX, drawn)
  const fill = tallestPx - drawn
  const empty = Math.max(0, HELD_SLOTS - cardPx.length)
  const next = { tallestPx }
  if (empty === 0) {
    return { room: next, blanks: fill > 0 ? [fill] : [] }
  }
  const each = Math.floor(fill / empty)
  const blanks = Array.from({ length: empty }, (_, i) => Math.max(1, i === empty - 1 ? fill - each * (empty - 1) : each))

  return { room: next, blanks }
}

/** An empty slot of `height` px: the cards' gray box with nothing in it, so the held room reads as room for agents. */
export function blankCard(height: number): Card {
  return stage(height, '', 'Empty agent slot')
}

